prompt --application/shared_components/navigation/lists/hall_of_fame_menu
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(50552015421097280)
,p_name=>'Hall of Fame Menu'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1 lvl',
'     , p.page_title label',
'     , apex_page.get_url(p_page => p.page_id) target',
'     , null is_current_list_entry',
'     , '''' image',
'     , '''' image_attribute',
'     , '''' image_alt_attribute',
'     , case ',
'        when p.page_id = 260 then ',
'          ''See previous Season winder who has won multiple-times''',
'        when p.page_id = 270 then ',
'          ''Players that got a combined score of -50 or lower on a weekend''',
'        when p.page_id = 280 then ',
'          ''Players with most aces on a weekend''',
'        when p.page_id = 290 then ',
'          ''Players with most Winning and Podium Streaks''',
'        end a1',
'from apex_application_pages p',
'where p.application_id = :APP_ID',
'  and p.page_id between 251 and 299',
'order by p.page_id',
''))
,p_list_status=>'PUBLIC'
,p_version_scn=>2338612594
);
end;
/
