prompt --application/shared_components/logic/application_computations/g_voting_allowed
begin
wwv_flow_imp_shared.create_flow_computation(
 p_id=>wwv_flow_imp.id(103453718465856266)
,p_computation_sequence=>10
,p_computation_item=>'G_VOTING_ALLOWED'
,p_computation_point=>'ON_NEW_INSTANCE'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation_processed=>'REPLACE_EXISTING'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'l_num number;',
'begin',
'',
'',
'select sum(noshow_registrations+noscore_participation)',
'into l_num',
'from (',
'      select sum(decode(issue_code, ''NOSHOW'', 1, 0)) noshow_registrations',
'           , sum(decode(issue_code, ''NOSCORE'', 1, 0)) noscore_participation',
'         from wmg_tournament_players',
'        where active_ind = ''Y''',
'          and player_id = :G_PLAYER_ID',
'          and tournament_session_id in (',
'            select ts.id',
'              from wmg_tournament_sessions ts',
'             where ts.tournament_id in (',
'   select ts.tournament_id',
'    from wmg_tournament_control tc',
'    join wmg_tournament_sessions ts on ts.id = tc.tournament_session_id',
'    where tournament_type_code = ''WMGT''               ',
'             )',
'          )',
')',
';',
'',
'return case when l_num is null then ''NO'' when l_num <=3 then ''YES'' else ''NO'' end;',
'end;',
''))
,p_computation_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with w_tournaments as (',
'  select id',
'       , lag(id) over (order by start_date, id) as prev_id',
'       , current_flag',
'  from wmg_tournaments',
')',
'',
'',
'/*',
'-- last 2 seasons',
'select id',
'from w_tournaments',
'where current_flag = ''Y''',
'union all',
'select prev_id',
'from w_tournaments',
'where current_flag = ''Y''',
'  and prev_id is not null',
'*/',
''))
,p_version_scn=>2409628573
);
end;
/
