begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(47017459917432127329)
,p_name=>'Oracle APEX Accounts'
,p_scheme_type=>'NATIVE_APEX_ACCOUNTS'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'procedure set_test_user',
'is',
'begin',
' /* ',
'   add to the Post-Auth procedure to fake a user',
'   set_test_user',
'  */',
' if :APP_USER != ''JRIMBLAS'' then',
'   return;',
' end if; ',
' select id',
'       , account',
'       , discord_id',
'       , discord_avatar',
'       , discord_discriminator',
'  into :G_PLAYER_ID',
'     , :G_DISCORD',
'     , :G_DISCORD_ID',
'     , :G_DISCORD_AVATAR',
'     , :G_DISCORD_DISCRIMINATOR',
'    from wmg_players',
'   where id = 46; -- 46 Squeezy , 7085 MACEO;',
'',
'end set_test_user;'))
,p_invalid_session_type=>'LOGIN'
,p_post_auth_process=>'set_test_user'
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>1
);
end;
