wwv_flow_imp_shared.create_plugin_std_attribute(
 p_id=>wwv_flow_imp.id(173854067691394015)
,p_plugin_id=>wwv_flow_imp.id(173845652810394019)
,p_name=>'INIT_JAVASCRIPT_CODE'
,p_is_required=>false
,p_depending_on_has_to_exist=>true
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre>',
'function(config){',
'',
'    // groupSelector = string',
'    // The CSS selector which will be queried in this region and will server as the base for Drag & Drop. Only the children/descendants of this element will be draggable.',
'    config.groupSelector = ''ul'';',
'',
'    // itemSelector = string',
'    // The CSS selector which will be queried in the element(s) returned by the ''groupSelector''. The found elements will be the draggable elements.',
'    config.itemSelector  = ''li'';',
'',
'    // handle = string',
'    // The CSS selector which will be queried in the element(s) returned by the ''itemSelector''. The found elements will be the drag-handles by which you can reposition the items.',
'    config.handle = null;',
'',
'    // distance = number',
'    // The distance the cursor has to move before the drag starts.',
'    config.distance = 5;',
'',
'    // dataIdFn = function',
'    // A function to return the element''s id. If not specified the element''s data-id attribute is used.',
'    config.dataIdFn = function (item) { return item.dataset.id }',
'',
'    return config;',
'}',
'</pre>'))
,p_help_text=>'Javascript initialization function which allows you to override any settings right before the button is created'
);
