prompt --application/shared_components/plugins/dynamic_action/unitedcodes_list_extension
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(47941185039724465410)
,p_plugin_type=>'DYNAMIC ACTION'
,p_name=>'UNITEDCODES_LIST_EXTENSION'
,p_display_name=>'United Codes List Extension'
,p_category=>'INIT'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('DYNAMIC ACTION','UNITEDCODES_LIST_EXTENSION'),'')
,p_javascript_file_urls=>'#PLUGIN_FILES#js/uclistextension.min.js'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'--',
'-- Package UC_LIST_EXTENSION needed in order for this to work',
'--'))
,p_api_version=>2
,p_render_function=>'UC_LIST_EXTENSION.render'
,p_ajax_function=>'UC_LIST_EXTENSION.ajax'
,p_standard_attributes=>'BUTTON'
,p_substitute_attributes=>true
,p_version_scn=>1
,p_subscribe_plugin_settings=>true
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Plug-ins Pro List Extension is an Oracle APEX plug-in designed to improve the user experience when adding new values to an existing List of Values (LOV). Users can quickly and easily add a new value to an existing Select List, Popup LOV, Radio Group,'
||' Checkbox, or Shuttle and automatically select the newly created value - all without leaving the page they are working on or losing their place in the application!',
'',
'',
'This plug-in should be used in combination with a modal window for the detail page.'))
,p_version_identifier=>'21.2'
,p_about_url=>'https://www.plug-ins-pro.com'
,p_files_version=>31
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(47941185468158462625)
,p_plugin_id=>wwv_flow_imp.id(47941185039724465410)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>'Page item'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>true
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(47507416818185266942)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'PI'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'This is the main setting of the plug-in. Please select an item in which new value will be returned.<br>',
unistr('The item must be set\00A0 on this page when the plugin is used so that JavaScript can access it.The item needs to be one of the following types :<br>'),
'<ul>',
'<li>PopupLov,</li>',
'<li>Select list,</li>',
'<li>Radio group,</li>',
'<li>Checkbox group,</li>',
'<li>Shuttle type</li>',
'</ul>',
'<br>',
'For the plugin to work, items must also use "Dynamic" List Of Values (LOV).<br>',
'In case of wrongly selected page item, an error message will appear as page render error.'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(47941185823939461433)
,p_plugin_id=>wwv_flow_imp.id(47941185039724465410)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>2
,p_display_sequence=>20
,p_prompt=>'Page returning item value'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>true
,p_is_translatable=>false
,p_examples=>'P200_DEPTNO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'This attribute decides the item name by returning a new value id.<br>',
'The Best approach is to find the primary key item through this setting.<br>',
'<br>',
'IMPORTANT: Do not forget to add the item into "Items to Return" on the DialogClose process in the modal window page!<br>',
'In case there is no item to return, fetch action will not be triggered.<br>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(47941186061048450104)
,p_plugin_id=>wwv_flow_imp.id(47941185039724465410)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_prompt=>'Action'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'set'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'This action is possible only on items that support multiple choice otherwise default behavior "Set Value" is taken by default.<br>',
'<br>',
'<p>',
'<h4>Set Value</h4>',
'When the action is set to "Set Value" and a new value id is created, the item gets replaced with new value.<br>',
'This setting is applied to the selected page item by default.',
'</p>',
'<p>',
'<h4>Append Value</h4>',
'When the action is set to "Append Value" and a new value id is created, the item adds a new value to the already existing stack.<br>',
'Multiple values setting on the item must be enabled so that action "Append Value" can take place.',
'</p>'))
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(47941187474076444156)
,p_plugin_attribute_id=>wwv_flow_imp.id(47941186061048450104)
,p_display_sequence=>10
,p_display_value=>'Set Value'
,p_return_value=>'set'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(47941186788771446666)
,p_plugin_attribute_id=>wwv_flow_imp.id(47941186061048450104)
,p_display_sequence=>20
,p_display_value=>'Append Value'
,p_return_value=>'append'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(47941298081588573010)
,p_plugin_id=>wwv_flow_imp.id(47941185039724465410)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>4
,p_display_sequence=>40
,p_prompt=>'Button location'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'stretch'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_examples=>'Default and suggestion to use is : "stretch" option'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Button location gets interesting while using "radio group", "checkbox group" or "shuttle" element with a lot of data to display.<br>',
'With this setting we can easily manage button position.<br>',
'<br>',
'Shuttle element has additional classes to be displayed among already existing buttons.<br>'))
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(47941308752031572244)
,p_plugin_attribute_id=>wwv_flow_imp.id(47941298081588573010)
,p_display_sequence=>10
,p_display_value=>'Stretch'
,p_return_value=>'stretch'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(47941309128393571111)
,p_plugin_attribute_id=>wwv_flow_imp.id(47941298081588573010)
,p_display_sequence=>20
,p_display_value=>'Top'
,p_return_value=>'top'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(47941309490320570418)
,p_plugin_attribute_id=>wwv_flow_imp.id(47941298081588573010)
,p_display_sequence=>30
,p_display_value=>'Center'
,p_return_value=>'center'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(47941309881856569525)
,p_plugin_attribute_id=>wwv_flow_imp.id(47941298081588573010)
,p_display_sequence=>40
,p_display_value=>'Bottom'
,p_return_value=>'bottom'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(47507537519577237792)
,p_plugin_attribute_id=>wwv_flow_imp.id(47941298081588573010)
,p_display_sequence=>50
,p_display_value=>'Popup LOV (inline)'
,p_return_value=>'popup-inline'
,p_help_text=>'Used only in case of PopupLOV to display button inline with other selectable entities.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(47507416818185266942)
,p_plugin_id=>wwv_flow_imp.id(47941185039724465410)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>5
,p_display_sequence=>5
,p_prompt=>'Type'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'PI'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'The main setting of the plug-in. With this option, we decide if we use a normal page item or an Interactive Grid column.'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(47507431837929265734)
,p_plugin_attribute_id=>wwv_flow_imp.id(47507416818185266942)
,p_display_sequence=>10
,p_display_value=>'Page item'
,p_return_value=>'PI'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(47507432257396263544)
,p_plugin_attribute_id=>wwv_flow_imp.id(47507416818185266942)
,p_display_sequence=>20
,p_display_value=>'Interactive Grid'
,p_return_value=>'IG'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(47507462381900251888)
,p_plugin_id=>wwv_flow_imp.id(47941185039724465410)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>6
,p_display_sequence=>10
,p_prompt=>'IG static name'
,p_attribute_type=>'TEXT'
,p_is_required=>true
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(47507416818185266942)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'IG'
,p_help_text=>'here we specify the static id of the interactive grid region. With this option, the plugin creates additional refresh actions needed in order plug in to work.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(47507477466450247295)
,p_plugin_id=>wwv_flow_imp.id(47941185039724465410)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>7
,p_display_sequence=>15
,p_prompt=>'IG column name'
,p_attribute_type=>'TEXT'
,p_is_required=>true
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(47507416818185266942)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'IG'
,p_examples=>'DEPTNO'
,p_help_text=>'This option is to specify the column name of the interactive grid region. With this option, the plugin connects the column and the button among other needed actions.'
);
