prompt --application/shared_components/navigation/search_config/players
begin
wwv_flow_imp_shared.create_search_config(
 p_id=>wwv_flow_imp.id(61250749270746322)
,p_label=>'Players'
,p_static_id=>'players'
,p_search_type=>'SIMPLE'
,p_location=>'LOCAL'
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select p.*',
'     , case when tp.active_ind = ''Y'' then',
'        ''Signup for '' || tp.week || '' at '' || tp.time_slot',
'      || case when tp.room_no is not null then '' | Room WMGT'' || tp.room_no end',
'       else '''' end signup',
'from wmg_players_v p',
'   , wmg_tournament_player_v tp',
'where p.id = tp.player_id (+)',
'  and tp.tournament_session_id (+) = :G_CURRENT_SESSION_ID',
''))
,p_searchable_columns=>'ACCOUNT:NAME:PLAYER_NAME:PREFERED_TZ:COUNTRY_CODE:COUNTRY:RANK_CODE:SIGNUP:DISCORD_ID'
,p_pk_column_name=>'ID'
,p_title_column_name=>'PLAYER_NAME'
,p_subtitle_column_name=>'RANK_NAME'
,p_description_column_name=>'SIGNUP'
,p_custom_01_column_name=>'PREFERED_TZ'
,p_link_target_type=>'REDIRECT_PAGE'
,p_link_target=>'f?p=&APP_ID.:120:&APP_SESSION.::&DEBUG.:120:P120_PLAYER_ID:&ID.'
,p_icon_source_type=>'URL'
,p_icon_class_column_name=>'AVATAR_IMAGE'
,p_icon_image_url=>'&AVATAR_IMAGE.'
,p_version_scn=>1
,p_authorization_scheme=>wwv_flow_imp.id(47017660094734127428)
);
end;
