'var a = lLink.match(/\#.+$/) || [""];  // extract a possible anchor',
'lLink = lLink.replace(/\#.+$/gi,"");',
'//lLink = lLink.replace(/\&tz\=[0-9]+\:[0-9]+/i, "") + ''\u0026tz=''+tzx + a[0];',
