,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var $ctx;',
'',
'function searchRows(searchTerm) {',
'//  $ctx = $("#report_table_votesRegion .tooltipImg, #report_table_votesRegion .tooltipImg[title]");',
'  $ctx = $("#report_table_votesRegion .tooltipImg");',
'',
'  // Remove previous marked elements and ensure they all show',
'  $ctx.unmark().parents("tr").show();',
'',
'  if (searchTerm) {',
'    // mark the search searchTerm and hide everything that didn''t get marked',
'    $ctx.mark(searchTerm, {',
'      done: function() {',
'',
'        $ctx.each(function(){',
'          let $row = $(this).parents("tr");',
'          if ( $row.find("mark").length === 0) { // if there''s no mark, hide the row',
'            $row.hide();',
'          }',
'        });',
'      }',
'    });',
'  }',
'',
'}',
'',
'function getDiff(nextDate) {',
'  const oneDay = 24 * 60 * 60 * 1000; // milliseconds in a day',
'  const oneHour = 1 * 60 * 60 * 1000; // milliseconds in an hour',
'  const nextD = new Date(nextDate);',
'  const diff = Math.abs(new Date() - nextD); // difference between now and the provided date',
'',
'  if (diff > (2*oneDay)) {',
'      return ''dh'';',
'  }',
'  if (diff > oneDay) {',
'    return ''dhm''; // difference is greater than a day',
'  }',
'  else if (diff > oneHour) {',
'      return ''hm''; // difference is greater than an hour',
'  }',
'  else {',
'    return ''ms''; // difference is less than an hour',
'  }',
'}',
'',
'function start_timer(time, title) {',
'    var layoutFormat;',
'    layoutFormat = getDiff(time);',
'$(".syotimer").syotimer({',
'  date: new Date(time),',
'  layout: layoutFormat,',
'  doubleNumbers: false,',
'  headTitle: title',
'});',
'}',
'',
'function courseTooltips() {',
'$(".tooltipImg").tooltip({',
'    content: function() {',
'      // Get the description and image URL from the "title" and "data-img-url" attributes',
'      var description = $(this).attr("title");',
'      var fact = $(this).data("fact");',
'      var imgUrl = $(this).data("img-url");',
'      var wmgtExcluded = $(this).hasClass("--wmgt-excludedY");',
'',
'      // Create an HTML string to include the description and the image',
'      var tooltipContent = "<div>" + description + "</div>";',
'      tooltipContent += "<img class=''courseIcon'' src=''" + imgUrl + "'' alt=''" + description + "'' />";',
'      if (wmgtExcluded) {',
'         tooltipContent += "<div class=''--wmgt-excluded-legend''>" + "This course will not be played in S14" + "</div>";',
'      }',
'      else {',
'        if (fact) {',
'            tooltipContent += "<div class=''legend u-color-6-text''>" + fact + "</div>";',
'        }',
'      }',
'',
'      return tooltipContent;',
'    }',
'});',
'}'))
