wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(30511297518551717)
,p_name=>'You''re Registered!'
,p_parent_plug_id=>wwv_flow_imp.id(34449741633298632)
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>10
,p_region_css_classes=>'-wm-animate-glow-blue'
,p_icon_css_classes=>'fa fa-check-square fa-anim-vertical-shake'
,p_region_template_options=>'#DEFAULT#:t-Region--showIcon:t-Region--accent3:t-Region--scrollBody:margin-top-none'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlightOff:t-Report--noBorders:t-Report--hideNoPagination'
,p_grid_row_css_classes=>'u-justify-content-center'
,p_grid_column_css_classes=>'room col-xxs-12 col-xs-12 col-sm-8 col-md-6 col-lg-5 col-xl-5 col-xxl-4'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with my_room as (',
'select p.tournament_session_id',
'     , nvl(p.prefered_tz, sessiontimezone) tz',
'     , p.time_slot',
'     , wmg_discord.avatar_link(p_discord_id => p.discord_id)',
'    || apex_escape.html(p.player_name) player',
'from wmg_tournament_player_v p',
'where p.active_ind = ''Y''',
'  and p.tournament_session_id = :G_CURRENT_SESSION_ID',
'  and p.player_id = :G_PLAYER_ID',
')',
'select r.*',
'    , to_char(local_tz, ''fmDy, fmMonth fmDD'') ',
'      || '', '' ',
'      || case when tz like ''US/%'' or tz like ''America%'' then',
'           ltrim(to_char(local_tz, ''HH:MI PM''), ''0'')',
'         else ',
'           to_char(local_tz, ''HH24:MI'')',
'         end',
'      || '' '' || tz at_local_time',
'from (',
'select r.player',
'     , to_utc_timestamp_tz(to_char(s.session_date + ts.day_offset, ''yyyy-mm-dd'') || ''T'' || r.time_slot) at time zone r.tz local_tz',
'     , r.tz',
'     , r.time_slot',
'from wmg_tournament_sessions s',
'   , wmg_time_slots_all_v ts',
'   , my_room r',
'where s.id = r.tournament_session_id',
'  and r.time_slot = ts.time_slot',
') r',
''))
,p_required_role=>'MUST_NOT_BE_PUBLIC_USER'
,p_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'from wmg_tournament_players p',
'   , wmg_tournament_sessions s',
'where p.tournament_session_id = s.id',
'  and p.active_ind = ''Y''',
'  and p.tournament_session_id = :G_CURRENT_SESSION_ID',
'  and p.player_id = :G_PLAYER_ID',
'  and s.rooms_open_flag is null'))
,p_display_condition_type=>'EXISTS'
,p_header=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="u-bold">When:</div>',
'<span class="your-tzRoomTime"></span><br>',
'',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_headings_type=>'NO_HEADINGS'
,p_query_num_rows=>200
,p_query_options=>'DERIVED_REPORT_COLUMNS'
