 p_id=>wwv_flow_imp.id(24766717629741008578)
,p_name=>'About the next courses'
,p_region_name=>'aboutNextCourses'
,p_parent_plug_id=>wwv_flow_imp.id(31642775272928413)
,p_template=>wwv_flow_imp.id(47017491752572127343)
,p_display_sequence=>50
