'  select s.session_date',
'       , nvl(ec.name, ''- TBD -'') easy_course',
'       , nvl(hc.name, ''- TBD -'') hard_course',
'       , (select count(*) from wmg_tournament_players p where p.tournament_session_id = s.tournament_session_id and p.active_ind = ''Y'') players',
'       , case when ec.id is null then ''u-vh'' else '''' end tbd_class',
'       , to_char(s.session_date, ''yyyy-mm-dd'') || ''T'' || ''00:00+00:00'' session_date_utc_str',
'       , case when s.session_date is null then null else to_utc_timestamp_tz(to_char(s.session_date, ''yyyy-mm-dd'') || ''T'' || ''00:00'') end session_date_utc',
'  from wmg_tournament_sessions_v s',
'     , wmg_courses ec',
'     , wmg_courses hc',
'  where s.easy_course_id = ec.id (+)',
'    and s.hard_course_id = hc.id (+)',
'    and s.completed_ind = ''N''',
'    and (s.open_registration_on is null or s.open_registration_on < localtimestamp)',
'    and s.tournament_id in (',
'      select id',
'        from wmg_tournaments',
'       where current_flag = ''Y''',
'  )',
'  order by session_date desc',
'  fetch first 1 rows only',
')',
', w_slots as (',
'select seq, day_offset, time_slot, prepared_time_slot, t',
'from wmg_time_slots_all_v',
'union all',
'select 0 seq, -1 day_offset, ''21:00'' time_slot, ''21:00 -1'' prepared_time_slot, ''21'' t',
'from dual',
')',
', next_room_timer as (',
'  select *',
'  from (',
'  select to_utc_timestamp_tz(to_char(s.session_date + slots.day_offset, ''yyyy-mm-dd'') || ''T'' || slots.time_slot) session_date_utc',
'       , to_char(s.session_date + slots.day_offset, ''yyyy-mm-dd'') || ''T'' || slots.time_slot || ''+00:00'' session_date_utc_str',
'       , decode(slots.seq, 0, ''Registration closes in'', 1, ''Next tournament starts in'', ''UTC '' || slots.time_slot || '' starts in'') title',
'       , s.session_date',
'  from next_session s',
'     , w_slots slots',
'  )',
'  where session_date_utc > systimestamp - NUMTODSINTERVAL(2, ''MINUTE'')',
'  order by session_date_utc',
' fetch first 1 rows only',
')',
'select ns.session_date -1 session_date',
'     , ns.easy_course',
'     , ns.hard_course',
'     , ns.players',
'     , ns.tbd_class',
'     , nr.session_date_utc_str countdown_timer',
'     , nr.title',
' from next_session ns',
'    , next_room_timer nr',
'where ns.session_date_utc + 1 > systimestamp',
'  and ns.session_date = nr.session_date (+)',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_headings_type=>'NO_HEADINGS'
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
