'     , r.player_id',
'     , r.player_name',
'     , r.discord_id',
'     , r.discord_avatar',
'     , r.country_code',
'     , r.country',
'     , r.season_total',
'     , r.rank_code',
'     , r.rank_name',
'     , r.rank_list_class',
'  from (',
'  select p.player_name',
'       , p.country_code',
'       , p.country',
'       , p.rank_code',
'       , p.rank_name',
'       , p.rank_list_class',
'       , p.discord_id',
'       , p.discord_avatar',
'       , decode(sp.w1_discard, ''Y'', 0, nvl(sp.w1_points,0))',
'       + decode(sp.w2_discard, ''Y'', 0, nvl(sp.w2_points,0))',
'       + decode(sp.w3_discard, ''Y'', 0, nvl(sp.w3_points,0))',
'       + decode(sp.w4_discard, ''Y'', 0, nvl(sp.w4_points,0))',
'       + decode(sp.w5_discard, ''Y'', 0, nvl(sp.w5_points,0))',
'       + decode(sp.w6_discard, ''Y'', 0, nvl(sp.w6_points,0))',
'       + decode(sp.w7_discard, ''Y'', 0, nvl(sp.w7_points,0))',
'       + decode(sp.w8_discard, ''Y'', 0, nvl(sp.w8_points,0))',
'       + decode(sp.w9_discard, ''Y'', 0, nvl(sp.w9_points,0))',
'       + decode(sp.w10_discard, ''Y'', 0, nvl(sp.w10_points,0))',
'       + decode(sp.w11_discard, ''Y'', 0, nvl(sp.w11_points,0))',
'       + decode(sp.w12_discard, ''Y'', 0, nvl(sp.w12_points,0)) season_total',
'     , sp.*',
'  from sessions_pivot sp',
'     , wmg_players_v p',
'  where p.id = sp.player_id',
') r',
')',
', w_rank as (',
'select rank() over (partition by f.rank_code order by f.pos) rank_pos',
'     , wmg_discord.avatar_link(f.discord_id, f.discord_avatar) avatar',
'     , f.*',
'from final f',
')',
'select p.*',
'from  w_rank p',
'    , wmg_ranks r',
'where p.rank_code = r.code',
'  and p.rank_pos <= 3',
'  and r.active_ind = ''Y''',
'order by r.display_seq desc, p.season_total desc, nls_upper(p.player_name)',
''))
,p_optimizer_hint=>'WITH_PLSQL'
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P1_TOURNAMENT_SESSION_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>250
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_break_cols=>'1'
,p_query_no_data_found=>'- No scores yet -'
,p_break_type_flag=>'REPEAT_HEADINGS_ON_BREAK_1'
,p_break_repeat_heading_format=>'<h5>Top #COLUMN_VALUE#s</h5>'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
