wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(65687278865700647)
,p_name=>'Top By Rank'
,p_region_name=>'leadersByRankRegion'
,p_parent_plug_id=>wwv_flow_imp.id(66835672221733416)
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>100
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--accent1:t-Region--noBorder:js-headingLevel-3:t-Region--scrollBody:margin-top-none'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--horizontalBorders:t-Report--hideNoPagination'
,p_new_grid_row=>false
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with ts as (',
'    select ts.id tournament_session_id',
'    from wmg_tournament_sessions ts',
'    where id = :G_CURRENT_SESSION_ID',
')',
'select p.*',
'from (',
'select p.tournament_session_id',
'     , p.pos',
'     , p.player_id',
'     , wmg_discord.avatar_link(pp.discord_id, pp.discord_avatar) avatar',
'     , pp.country_code',
'     , pp.country',
'     , pp.player_name',
'     , p.easy',
'     , p.hard',
'     , p.total_score',
'     , case when p.total_score <= -50 then ''fa-anim-flash'' else '''' end big_fifty',
'     , decode(p.player_id, :G_PLAYER_ID, ''mark'', '''') selected_player',
'     , case when p.pos = 1 then ''<i class="em em-trophy" aria-role="presentation" aria-label="TROPHY"></i>'' else '''' end trophy',
'     , pp.rank_code',
'     , pp.rank_name',
'     , pp.rank_list_class',
'    , rank() over (partition by p.rank_code order by p.pos) rank_pos',
'from wmg_tournament_session_points_v p',
'   , ts',
'   , wmg_players_v pp',
'where p.tournament_session_id = ts.tournament_session_id',
'  and p.player_id = pp.id',
') p',
', wmg_ranks r',
'where p.rank_code = r.code',
'  and p.rank_pos <= 3',
'  and r.active_ind = ''Y''',
'order by r.display_seq desc, p.rank_pos, p.pos, nls_upper(p.player_name)',
''))
,p_optimizer_hint=>'WITH_PLSQL'
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P1_WEEK,P1_TOURNAMENT_SESSION_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>250
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_break_cols=>'1'
,p_query_no_data_found=>'- No scores yet -'
,p_break_type_flag=>'REPEAT_HEADINGS_ON_BREAK_1'
,p_break_repeat_heading_format=>'<h5>Top #COLUMN_VALUE#s</h5>'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
