wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(7117909474948774118)
,p_name=>'Your Assigned Room'
,p_parent_plug_id=>wwv_flow_imp.id(34449741633298632)
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>50
,p_region_css_classes=>'-wm-animate-glow-blue'
,p_icon_css_classes=>'fa fa-bell-o fa-anim-horizontal-shake'
,p_region_template_options=>'#DEFAULT#:t-Region--showIcon:t-Region--accent1:t-Region--scrollBody:margin-top-none'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlightOff:t-Report--noBorders:t-Report--hideNoPagination'
,p_grid_row_css_classes=>'u-justify-content-center'
,p_grid_column_css_classes=>'room col-xxs-12 col-xs-12 col-sm-8 col-md-6 col-lg-5 col-xl-5 col-xxl-4'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with my_room as (',
'select p.tournament_session_id, p.time_slot, p.room_no',
'     , nvl(p.prefered_tz, sessiontimezone) tz',
'     , t.day_offset',
'from wmg_tournament_player_v p',
'   , wmg_time_slots_all_v t',
'where t.time_slot = p.time_slot',
'  and p.active_ind = ''Y''',
'  and p.tournament_session_id = :G_CURRENT_SESSION_ID',
'  and p.player_id = :G_PLAYER_ID',
')',
'select room_no',
'     , players',
'     , to_char(local_tz, ''fmDy, fmMonth fmDD'') ',
'      || '', '' ',
'      || case when tz like ''US/%'' or tz like ''America%'' then',
'           ltrim(to_char(local_tz, ''HH:MI PM''), ''0'')',
'         else ',
'           to_char(local_tz, ''HH24:MI'')',
'         end',
'      || '' '' || tz at_local_time',
'from (',
'select p.tournament_player_id',
'     , case when s.rooms_open_flag = ''Y'' then nvl2(p.room_no, t.prefix_room_name, '''') || p.room_no else '''' end room_no',
'     , case when s.rooms_open_flag = ''Y'' then '''' else row_number() over (order by p.tournament_player_id) || '': '' end',
'    || wmg_discord.avatar_link(p_discord_id => p.discord_id)',
'    || apex_escape.html(p.player_name)',
'    || case when p.rank_code = ''NEW'' then ''<span class="'' || p.rank_list_class || '' tooltip" title="'' || p.rank_name || ''"></span>'' end players',
'     , to_utc_timestamp_tz(to_char(s.session_date + r.day_offset , ''yyyy-mm-dd'') || ''T'' || p.time_slot) at time zone r.tz local_tz',
'     , r.tz',
'from wmg_tournament_player_v p',
'   , wmg_tournament_sessions s',
'   , wmg_tournaments t',
'   , my_room r',
'where s.id =  p.tournament_session_id',
'  and s.tournament_id = t.id',
'  and p.active_ind = ''Y''',
'  and p.tournament_session_id = r.tournament_session_id',
'  and p.time_slot = r.time_slot',
'  and p.room_no = r.room_no',
'  and s.rooms_open_flag = ''Y''',
')',
'order by tournament_player_id',
''))
,p_required_role=>'MUST_NOT_BE_PUBLIC_USER'
,p_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'from wmg_tournament_players p',
'   , wmg_tournament_sessions s',
'where p.tournament_session_id = s.id',
'  and p.active_ind = ''Y''',
'  and p.tournament_session_id = :G_CURRENT_SESSION_ID',
'  and p.player_id = :G_PLAYER_ID',
'  and s.rooms_open_flag = ''Y''',
'  and to_utc_timestamp_tz(to_char(s.session_date, ''yyyy-mm-dd'') || ''T'' || p.time_slot) > systimestamp - NUMTODSINTERVAL(2, ''MINUTE'')'))
,p_display_condition_type=>'EXISTS'
,p_header=>wwv_flow_string.join(wwv_flow_t_varchar2(
'When:<br>',
'<span class="your-tzRoomTime"></span><br>',
'Code:',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_headings_type=>'NO_HEADINGS'
,p_query_num_rows=>200
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_break_cols=>'1'
,p_break_before_row=>'<hr>'
,p_break_generic_column=>'WMGT #ROOM_NO#'
,p_break_type_flag=>'REPEAT_HEADINGS_ON_BREAK_1'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
