wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(55207721238162208)
,p_name=>'Season Courses'
,p_region_name=>'seasonCourses'
,p_parent_plug_id=>wwv_flow_imp.id(35893733074904551)
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noBorder:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight:t-Report--hideNoPagination'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with w_options as (',
' select build_option_status voting',
'   from apex_application_build_options',
'  where application_id = :APP_ID ',
'  and build_option_name = ''Feature: Course Voting''',
')',
', tournament_courses as (',
'    select s.round_num',
'         , count(*) over () setup_weeks',
'         , s.week',
'         , s.easy_course_code',
'         , s.easy_course_name',
'         , to_char(apex_markdown.to_html(e.factoids, p_embedded_html_mode => ''PRESERVE'')) easy_factoids',
'         , '''' easy_tournament_excluded_flag',
'         , s.hard_course_code',
'         , s.hard_course_name',
'         , to_char(apex_markdown.to_html(h.factoids, p_embedded_html_mode => ''PRESERVE'')) hard_factoids',
'         , '''' hard_tournament_excluded_flag',
'         , s.easy_course_id',
'         , s.easy_release_order',
'         , s.hard_course_id',
'         , s.hard_release_order',
'         , case ',
'             when s.completed_ind = ''Y'' then ''white_check_mark''',
'             when (s.open_registration_on is null or s.open_registration_on < localtimestamp) then ''golf''',
'              else ''clock1'' ',
'           end status',
'      -- halloween',
'      --   , case when s.completed_ind = ''Y'' then ''skull'' else ''jack_o_lantern'' end status',
'         , s.session_date',
'         , s.completed_ind',
'    from wmg_tournament_sessions_v s',
'       , wmg_courses e',
'       , wmg_courses h',
'    where s.tournament_id in (',
'        select id',
'          from wmg_tournaments',
'         where current_flag = ''Y''',
'    )',
'      and s.easy_course_id = e.id (+)',
'      and s.hard_course_id = h.id (+)',
')',
', missing_easy as (',
'select round_num',
'     , easy_course_group',
'     , easy_course',
'     , easy_name',
'     , easy_tournament_excluded_flag',
'     , '''' hard_course',
'     , '''' hard_name',
'     , status',
'     , order_by',
'     , release_order',
'     , factoids easy_factoids',
'     , '''' hard_factoids',
'from (',
'select to_number(null) round_num',
'     , e.course_group easy_course_group',
'     , e.code easy_course',
'     , tce.easy_course_code',
'     , e.name easy_name',
'     , e.tournament_excluded_flag easy_tournament_excluded_flag',
'    -- , case when e.release_order <= 8 then ''zzz'' else ''lock'' end status',
'     , ''lock'' status',
'    -- halloween',
'    -- , ''skull_and_crossbones'' status',
'    -- , case when e.release_order <= 8 then 99 else 2 end order_by',
'     , 1 order_by',
'     , e.release_order',
'     , e.factoids',
'from wmg_courses e',
'   , tournament_courses tce',
'where e.course_mode = ''E''',
'  and e.code = tce.easy_course_code (+)',
')',
'join w_options on 1=1 ',
'where easy_course_code is null',
'  and w_options.voting = ''Exclude''',
')',
', missing_hard as (',
'  select round_num',
'       , hard_course_group',
'       , '''' easy_course',
'       , '''' easy_name',
'       , hard_course',
'       , hard_name',
'       , hard_tournament_excluded_flag',
'       , status',
'       , order_by',
'       , release_order',
'       , '''' easy_factoids',
'       , factoids hard_factoids',
'  from (',
'    select to_number(null) round_num',
'         , h.course_group hard_course_group',
'         , h.code hard_course',
'         , h.name hard_name',
'         , tch.hard_course_code',
'         , h.tournament_excluded_flag hard_tournament_excluded_flag',
'         , ''lock'' status',
'        -- halloween',
'        -- , ''skull_and_crossbones'' status',
'        -- , case when e.release_order <= 8 then 99 else 2 end order_by',
'         , 1 order_by',
'         , h.release_order',
'         , h.factoids',
'    from wmg_courses h',
'       , tournament_courses tch',
'    where h.course_mode = ''H''',
'      and h.code = tch.hard_course_code (+)',
'      and h.id not in (select easy_course_id from tournament_courses)',
'  )',
'join w_options on 1=1 ',
'  where hard_course_code is null',
'  and w_options.voting = ''Exclude''',
')',
'select /* q("pending") */ e.round_num',
'     , '''' last_week',
'     , '''' url',
'     , e.easy_course',
'     , e.easy_name',
'     , e.easy_tournament_excluded_flag',
'     , e.easy_factoids',
'     , h.hard_course',
'     , h.hard_name',
'     , h.hard_tournament_excluded_flag',
'     , h.hard_factoids',
'     , coalesce(e.status, h.status) status',
'     , '''' current_status',
'     , case ',
'         when  coalesce(e.status, h.status) = ''lock'' then ''Pending to be played''',
'         else ''Not eligible'' end status_title',
'     , coalesce(e.order_by, h.order_by) order_by',
'     , coalesce(e.release_order, h.release_order) course_order',
'from missing_easy e',
'full outer join missing_hard h',
'on e.easy_course_group = h.hard_course_group',
'union all',
'select c.round_num',
'     , '''' last_week',
'--     , apex_page.get_url(p_page => 60, p_items => ''P60_WEEK'', p_values => c.week) url',
'     , ''apex.page.submit({request: "VIEW_WEEK", set: {"P1_VIEW_WEEK": "'' || c.week || ''"}});'' url',
'     , nvl(c.easy_course_code, ''-?-'') easy_course_code',
'     , nvl(c.easy_course_name, ''TBD'') easy_name',
'     , c.easy_tournament_excluded_flag',
'     , c.easy_factoids',
'     , nvl(c.hard_course_code, ''-?-'') hard_course_code',
'     , nvl(c.hard_course_name, ''TBD'') hard_name',
'     , c.hard_tournament_excluded_flag',
'     , c.hard_factoids',
'     , c.status',
'     , decode(c.status',
'          , ''golf'', '' -wm-animate-glow-blue''',
'          , ''jack_o_lantern'', '' -wm-animate-glow-blue''',
'          , '''') current_status',
'     , decode(c.status',
'          , ''white_medium_square'', ''Pending to be played''',
'          , ''white_check_mark'', ''Already played''',
'          , ''skull'', ''Already played''',
'          , ''golf'', ''Current tournament courses''',
'          , ''jack_o_lantern'', ''Current tournament courses''',
'          , ''clock1'', ''Future week!''',
'          , ''o'', ''Not available'', ''''',
'          ) status_title',
'     , 1 order_by',
'     , coalesce(c.easy_release_order, c.hard_release_order) course_order',
'  from tournament_courses c',
' where c.round_num is not null -- make sure at least a round is defined',
'union all -- Buffer Week',
'select to_number(null) round_num',
'     , case when level + next_round_num = 12 then ''Y'' else '''' end last_week',
'     , '''' url',
'     , ''-?-'' easy_course',
'     , ''TBD'' easy_name',
'     , '''' easy_tournament_excluded_flag',
'     , '''' easy_factoids',
'     , ''-?-'' hard_course',
'     , ''TBD'' hard_name',
'     , '''' hard_tournament_excluded_flag',
'     , '''' hard_factoids',
'     , ''gift'' status',
'     , '''' current_status',
'     , ''TBD'' status_title',
'     , 1 order_by',
'     , 0 course_order     ',
'from (',
' select nvl(max(c.round_num),0) + 1 next_round_num',
' from tournament_courses c',
')',
'join w_options on 1 = 1',
'where next_round_num <= 12 -- 12 week season',
'  and w_options.voting = ''Exclude''',
'connect by level <= greatest(12 - next_round_num + 1, 0)',
'--  and not exists (select 1 from tournament_courses where completed_ind = ''N'') -- only add the TBD line when the current tournament is not finished',
'order by order_by, round_num, course_order,last_week desc',
''))
,p_plug_caching=>'CACHE'
,p_plug_caching_max_age_in_sec=>172800
,p_plug_cache_depends_on_items=>'APP_REQUEST_DATA_HASH'
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>12
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_comment=>'The URL param sets and item and submits because the region is cached and the URLs cannot contain the users session_id'
);
wwv_flow_imp_page.create_report_columns(
 p_id=>wwv_flow_imp.id(55207857972162209)
,p_query_column_id=>1
,p_column_alias=>'ROUND_NUM'
,p_column_display_sequence=>10
,p_column_heading=>'Round'
