 p_id=>wwv_flow_imp.id(93505573815001622)
,p_query_column_id=>5
,p_column_alias=>'EASY_COURSE'
,p_column_display_sequence=>20
,p_column_heading=>'Easy'
,p_use_as_row_header=>'N'
,p_column_html_expression=>wwv_flow_string.join(wwv_flow_t_varchar2(
'{case EASY_NAME/}',
'{when TBD /}<span class="tooltip" title="#EASY_NAME#">#EASY_COURSE#</span>',
'{otherwise/}',
'    {case EASY_ALLOW_DOWN_VOTE/}',
'    {when Y/}',
'    {case EASY_VOTE_CLASS/}',
'    {when hidedown/}',
'    <span class="t-Button t-Button--noLabel t-Button--icon t-Button--link fa fa-square-selected-o receiveVote voteUp" data-code="#EASY_COURSE#" aria-hidden="true" title="Voted!"></span>',
'    {otherwise/}',
