wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(98588138116842822)
,p_name=>'{Voting: Public View}'
,p_parent_plug_id=>wwv_flow_imp.id(107460726884333111)
,p_template=>wwv_flow_imp.id(47017496920405127346)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlightOff:t-Report--hideNoPagination'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with tournament_courses as (',
'    select s.round_num',
'         , count(*) over () setup_weeks',
'         , s.week',
'         , s.easy_course_code',
'         , s.easy_course_name',
'         , s.hard_course_code',
'         , s.hard_course_name',
'         , s.easy_course_id',
'         , s.easy_release_order',
'         , s.hard_course_id',
'         , s.hard_release_order',
'         , case ',
'             when s.completed_ind = ''Y'' then ''white_check_mark''',
'             when (s.open_registration_on is null or s.open_registration_on < localtimestamp) then ''golf''',
'              else ''clock1'' ',
'           end status',
'      -- halloween',
'      --   , case when s.completed_ind = ''Y'' then ''skull'' else ''jack_o_lantern'' end status',
'         , s.session_date',
'         , s.completed_ind',
'    from wmg_tournament_sessions_v s',
'       , wmg_courses e',
'       , wmg_courses h',
'    where s.tournament_id in (',
'        select id',
'          from wmg_tournaments',
'         where current_flag = ''Y''',
'    )',
'      and s.easy_course_id = e.id (+)',
'      and s.hard_course_id = h.id (+)',
')',
', w_votes as (',
'  select course_id, sum(vote) votes',
'  from wmg_course_vote',
'  group by course_id',
')',
', w_player_votes as (',
'  select course_id, vote, case vote when 1 then ''up'' when -1 then ''down'' else null end vote_selection ',
'  from wmg_course_vote',
'  where player_id = nvl(:G_PLAYER_ID,0)',
')',
', missing_easy as (',
'select round_num',
'     , easy_course_group',
'     , easy_course',
'     , easy_name',
'     , '''' hard_course',
'     , '''' hard_name',
'     , status',
'     , release_order',
'     , votes easy_votes',
'     , vote_class easy_vote_class',
'from (',
'select to_number(null) round_num',
'     , e.course_group easy_course_group',
'     , e.code easy_course',
'     , tce.easy_course_code',
'     , e.name easy_name',
'     , ''lock'' status',
'     , e.release_order',
'     , v.votes',
'     , decode(pv.vote_selection, null, ''show'', ''hide'' || pv.vote_selection) vote_class',
'from wmg_courses e',
'   , w_votes v',
'   , w_player_votes pv',
'   , tournament_courses tce',
'where e.course_mode = ''E''',
'  and e.code = tce.easy_course_code (+)',
'  and e.id = v.course_id (+)',
'  and e.id = pv.course_id (+)',
')',
'where easy_course_code is null',
'  and easy_course in ( ',
'    select column_value from apex_string.split(wmg_util.get_param(''VOTING_AVAILABLE_EASY''), '':'')',
'    union',
'    select code from wmg_courses where course_mode = ''E'' and wmg_util.get_param(''VOTING_AVAILABLE_EASY'') is null',
'  )',
')',
', missing_hard as (',
'  select round_num',
'       , hard_course_group',
'       , '''' easy_course',
'       , '''' easy_name',
'       , hard_course',
'       , hard_name',
'       , status',
'       , release_order',
'       , votes hard_votes',
'       , vote_class hard_vote_class',
'  from (',
'    select to_number(null) round_num',
'         , h.course_group hard_course_group',
'         , h.code hard_course',
'         , h.name hard_name',
'         , tch.hard_course_code',
'         , ''lock'' status',
'         , h.release_order',
'         , v.votes',
'         , decode(pv.vote_selection, null, ''show'', ''hide'' || pv.vote_selection) vote_class',
'    from wmg_courses h',
'       , w_votes v',
'       , w_player_votes pv',
'       , tournament_courses tch',
'    where h.course_mode = ''H''',
'      and h.code = tch.hard_course_code (+)',
'      and h.id in (select ac.id from wmg_courses ac where ac.course_mode = ''H'' minus select easy_course_id from tournament_courses)',
'      and h.id = v.course_id (+)',
'      and h.id = pv.course_id (+)',
'  )',
' where hard_course_code is null',
'   and hard_course in ( ',
'    select column_value from apex_string.split(wmg_util.get_param(''VOTING_AVAILABLE_HARD''), '':'')',
'    union',
'    select code from wmg_courses where course_mode = ''H'' and wmg_util.get_param(''VOTING_AVAILABLE_HARD'') is null',
'  )',
')',
', w_easy as (',
'select /* q("easy_votes") */ e.easy_votes easy_votes',
'     , case when e.easy_votes is not null and rank() over (order by e.easy_votes desc nulls last) = 1 then ''top'' end easy_votes_top',
'     , row_number() over (order by e.easy_votes desc nulls last, e.easy_course_group) easy_vote_order',
'     , e.easy_course',
'     , e.easy_course_group',
'     , e.easy_name',
'     , e.easy_vote_class',
'     , e.status',
'     , case ',
'         when e.status = ''lock'' then ''Voting open''',
'         else ''Not eligible'' end status_title',
'     , e.release_order course_order',
'from missing_easy e',
')',
', w_hard as (',
'select /* q("hard_votes") */ h.hard_votes',
'     , case when h.hard_votes is not null and rank() over (order by h.hard_votes desc nulls last) = 1 then ''top'' end hard_votes_top',
'     , row_number() over (order by h.hard_votes desc nulls last, h.hard_course_group) hard_vote_order',
'     , h.hard_course',
'     , h.hard_course_group',
'     , h.hard_name',
'     , h.hard_vote_class',
'     , h.status',
'     , case ',
'         when h.status = ''lock'' then ''Voting open''',
'         else ''Not eligible'' end status_title',
'     , h.release_order course_order',
'from missing_hard h',
')',
'select e.easy_vote_order',
'     , h.hard_vote_order',
'     , e.easy_votes',
'     , e.easy_votes_top',
'     , e.easy_course',
'     , e.easy_name',
'     , e.easy_vote_class',
'     , '''' easy_factoids',
'     , h.hard_course',
'     , h.hard_name',
'     , h.hard_vote_class',
'     , '''' hard_factoids',
'     , h.hard_votes',
'     , h.hard_votes_top',
'     , coalesce(e.status, h.status) status',
'     , case ',
'         when  coalesce(e.status, h.status) = ''lock'' then ''Voting open''',
'         else ''Not eligible'' end status_title',
'     , coalesce(e.course_order, h.course_order) course_order',
'from (select * from w_easy where easy_votes is not null) e',
'full outer join (select * from w_hard where hard_votes is not null) h',
'on e.easy_vote_order = h.hard_vote_order',
'union all',
'select /* q("with_votes") */',
'       e.easy_vote_order',
'     , h.hard_vote_order',
'     , e.easy_votes',
'     , e.easy_votes_top',
'     , e.easy_course',
'     , e.easy_name',
'     , e.easy_vote_class',
'     , '''' easy_factoids',
'     , h.hard_course',
'     , h.hard_name',
'     , h.hard_vote_class',
'     , '''' hard_factoids',
'     , h.hard_votes',
'     , h.hard_votes_top',
'     , coalesce(e.status, h.status) status',
'     , case ',
'         when  coalesce(e.status, h.status) = ''lock'' then ''Voting open''',
'         else ''Not eligible'' end status_title',
'     , coalesce(e.course_order, h.course_order) course_order',
'from (select * from w_easy where easy_votes is null) e',
'full outer join (select * from w_hard where hard_votes is null) h',
'on e.easy_course_group = h.hard_course_group',
'order by 1 nulls last, 3',
''))
,p_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'not (:G_PLAYER_ID is not null ',
'or apex_authorization.is_authorized (p_authorization_name => ''Tournament Admin'' ))'))
,p_display_when_cond2=>'PLSQL'
,p_display_condition_type=>'EXPRESSION'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>50
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_required_patch=>wwv_flow_imp.id(96682701070309865)
,p_comment=>'The URL param sets and item and submits because the region is cached and the URLs cannot contain the users session_id'
);
