wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(54920172188042439)
,p_plug_name=>'For the rest of the story'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(47017557400631127370)
,p_plug_display_sequence=>29
,p_plug_grid_column_span=>7
,p_plug_display_column=>3
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'If you like drama and fantastical stories, keep reading. Otherwise, just dismiss this section, which would be perfectly fine.<br>',
'',
'But if you want to know why the WMGT was abruptly paused, keep reading.<br>',
'',
'Actually, I don''t understand why myself, as many of the details don''t make sense. But I''ll try to present you with the conversations that happened ',
' and let you form your own opinion.',
'<br>',
'<br>',
'I''m now banned from the Walkabout Mini Golf server, forever, and for what? For promoting their game and making the weekly tournament better than it ever was?',
'<br>',
'<br>',
'-El Jorge',
'<br>',
'<br>',
'<i>Must be logged in to read</i>',
'<br>',
'',
''))
,p_plug_display_condition_type=>'FUNCTION_BODY'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if nvl(apex_util.get_preference(''NO_GOLFGATE_DRAMA''), ''N'') = ''Y'' then',
'  return false;',
'end if;',
'if :G_PLAYER_ID in ( ',
'      25  -- Bear',
'    , 39  -- FIRE',
'    , 6906 -- wyatt',
'    ) ',
'    or :APP_USER like ''BJKRHINO7%'' then',
'    return false;',
'else',
'  if :G_PLAYER_ID in (3212, 1546, 6912, 662, 8426, 9046, 7490) ',
'   or :APP_USER like ''THERE.WAS.SUN%''',
'   or :APP_USER like ''JORGE%''',
'  then',
'  -- 585=mickullen, 3212=gmoney, 1546 = The great Golfer, 6912 = SpareBullet, 662 NEDR, 8426 unixdude',
'  -- 9046 sandwichartista, 7490 OpusMcGraw',
'  return true;',
'  else',
'  return false;',
'  end if;',
'end if;',
'',
'return true;'))
,p_plug_display_when_cond2=>'PLSQL'
,p_required_patch=>wwv_flow_imp.id(47017459699454127328)
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
