wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(107460808337333112)
,p_name=>'Bot Status'
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>19
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--stacked:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlightOff:t-Report--inline:t-Report--hideNoPagination'
,p_grid_column_span=>7
,p_display_column=>3
,p_display_point=>'REGION_POSITION_05'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select *',
'from (',
'select r.id',
'     , r.source_code',
'     , jt.status',
'     , jt.uptime',
'     , wmg_rest_api.format_uptime(jt.uptime, ''Y'') uptime_format',
'     , jt.scorecardapi_successful success_count',
'     , jt.scorecardapi_failed     failure_count',
'     , r.duration_ms',
'     , apex_util.get_since(r.created_on) as_of',
'     , r.error_message',
'from wmg_rest_request r ',
'  , json_table(',
'  r.response_payload, ''$''',
'  columns (',
'    status                         varchar2(20) path ''$.status''',
'  , timestamp_utc                  varchar2(50) path ''$.timestamp''',
'  , uptime                         number       path ''$.uptime''',
'  , version                        varchar2(50) path ''$.version''',
'  , health_checks_total            number       path ''$.health_checks_total''',
'  , health_checks_failure_rate     number       path ''$.health_checks_failure_rate''',
'  , components_healthy             number       path ''$.components_healthy''',
'  , components_total               number       path ''$.components_total''',
'  , scorecardapi                   number       path ''$.scorecardApi''',
'  , scorecardapi_successful        number       path ''$.scorecardApi_successful''',
'  , scorecardapi_failed            number       path ''$.scorecardApi_failed''',
'  , resultsapi                     number       path ''$.resultsApi''',
'  , resultsapi_successful          number       path ''$.resultsApi_successful''',
'  , resultsapi_failed              number       path ''$.resultsApi_failed''',
'  )',
') jt',
'where r.source_code = ''WMG_SCORECARD_BOT''',
'order by r.id desc',
'fetch first 1 row only',
')',
'union all',
'select *',
'from (',
'select r.id',
'     , r.source_code',
'     , b.status',
'     , b.uptime',
'     , wmg_rest_api.format_uptime(b.uptime, ''Y'') uptime_format',
'     , jt.requests success_count',
'     , jt.error_count failure_count',
'     , r.duration_ms',
'     , apex_util.get_since(r.created_on) as_of',
'     , r.error_message',
'from wmg_rest_request r ',
'  , json_table(',
'  r.response_payload, ''$''',
'  COLUMNS (',
'    status     varchar2(20) path ''$.status'',',
'    uptime     number       PATH ''$.uptime''',
'  )',
'  ) b  ',
'  , json_table(',
'  r.response_payload, ''$.metrics''',
'  COLUMNS (',
'    requests   NUMBER       PATH ''$.requests'',',
'    error_count     NUMBER       PATH ''$.errors'',',
'    -- commands object',
'    register   NUMBER       PATH ''$.commands.register'',',
'    unregister NUMBER       PATH ''$.commands.unregister'',',
'    mystatus   NUMBER       PATH ''$.commands.mystatus'',',
'    timezone   NUMBER       PATH ''$.commands.timezone'',',
'    -- memoryUsage object',
'    rss        NUMBER       PATH ''$.memoryUsage.rss'',',
'    heapTotal  NUMBER       PATH ''$.memoryUsage.heapTotal'',',
'    heapUsed   NUMBER       PATH ''$.memoryUsage.heapUsed'',',
'    external   NUMBER       PATH ''$.memoryUsage.external'',',
'    arrayBuffers NUMBER     PATH ''$.memoryUsage.arrayBuffers'',',
'    -- cpuUsage object',
'    cpu_user   NUMBER       PATH ''$.cpuUsage.user'',',
'    cpu_system NUMBER       PATH ''$.cpuUsage.system''',
'  )',
') jt',
'where r.source_code = ''WMGT_BOT''',
'order by r.id desc',
'fetch first 1 row only',
')',
'order by 2',
''))
,p_required_role=>wwv_flow_imp.id(47017660094734127428)
,p_ajax_enabled=>'Y'
