wwv_flow_imp_page.create_page_branch(
 p_id=>wwv_flow_imp.id(36984535587622012)
,p_branch_name=>'Go Match existing player to Discord account'
,p_branch_action=>'f?p=&APP_ID.:17:&SESSION.::&DEBUG.:::&success_msg=#SUCCESS_MSG#'
,p_branch_point=>'BEFORE_HEADER'
,p_branch_type=>'REDIRECT_URL'
,p_branch_sequence=>20
,p_branch_condition_type=>'FUNCTION_BODY'
,p_branch_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' l_players_tbl  wmg_util.tab_keyval_type;',
'begin ',
'',
'    if :P1_DO_NOT_MATCH_FLAG = ''Y'' or :G_PLAYER_ID is not null then',
'       -- player doesn''t want to be matched or it''s already a player',
'       return false;',
'    end if;',
'',
'    wmg_util.possible_player_match(',
'        p_discord_account => :G_DISCORD',
'      , p_discord_name    => :G_DISCORD_NAME',
'      , p_discord_id      => :G_DISCORD_ID',
'      , x_players_tbl     => l_players_tbl',
'    );',
'',
'    if l_players_tbl is null then ',
'       -- if there is no match, either they are a match already or we don''t have history',
'       return false;',
'    else',
'       return l_players_tbl.count > 0;',
'    end if;',
'end;'))
,p_branch_condition_text=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_required_patch=>wwv_flow_imp.id(47017459699454127328)
,p_branch_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'We''re going to stop allowing users to match to a previous player until we have a better mechanism.',
'We''ll merge them manually.'))
);
