wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(2347725890845518533)
,p_computation_sequence=>10
,p_computation_item=>'G_CURRENT_SESSION_ID'
,p_computation_point=>'BEFORE_HEADER'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select nvl(max(id),-1)',
'from (',
'select s.id',
'from wmg_tournament_sessions s',
'where s.tournament_id in (',
'    select id',
'      from wmg_tournaments',
'     where current_flag = ''Y''',
')',
'and s.session_date+1 >= trunc(current_timestamp)',
'and s.completed_ind = ''N''',
'and (s.open_registration_on is null or s.open_registration_on < localtimestamp)',
'order by s.session_date desc',
'fetch first 1 rows only',
')'))
);
