 p_id=>wwv_flow_imp.id(44054890437955823)
,p_name=>'{Courses}'
,p_parent_plug_id=>wwv_flow_imp.id(44053350502955808)
,p_template=>wwv_flow_imp.id(47017496920405127346)
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with course_stats as (',
'  select tc.course_id, max(ts.session_date) last_played, count(*) played_count',
'  from wmg_tournament_sessions ts',
'     , wmg_tournament_courses tc',
'  where tc.tournament_session_id = ts.id',
' group by tc.course_id',
')',
'select c.course_id id',
'     , c.release_order',
'     , c.release_date',
'     , c.code',
'     , c.name',
'     , c.name course_name',
'     , apex_markdown.to_html(c.factoids, p_embedded_html_mode => ''PRESERVE'') factoids',
'     , c.course_mode',
'     , c.course_par',
'     , c.course_emoji',
'     , :BUCKET || c.course_emoji || ''.webp'' emoji_url',
'     , :BUCKET || c.code || ''_FULL.jpg'' icon',
'     , s.last_played',
'     , nvl(s.played_count, 0) played_count',
'  from wmg_courses_v c',
'     , course_stats s',
'where c.course_id = s.course_id (+)',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>15
