,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ROUND_ID,',
'       PLAYER_ID,',
'       PLAYER_NAME,',
'       COURSE_CODE,',
'       S1,',
'       S2,',
'       S3,',
'       S4,',
'       S5,',
'       S6,',
'       S7,',
