,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with stats as (',
'    select tp.player_id, max(ts.session_date) last_played',
'      from wmg_tournament_players tp',
'         , wmg_tournament_sessions ts',
'    where tp.tournament_session_id = ts.id',
'    group by tp.player_id',
')',
', current_tournament as (',
'    select tp.player_id',
'      from wmg_tournament_players tp',
'     where tournament_session_id = :G_CURRENT_SESSION_ID ',
')',
'select ID,',
'       player_name,',
'       ACCOUNT,',
'       NAME,',
'       rank_code,',
'       rank_name,',
'       rank_list_class,',
'       rank_profile_class,',
'       ACCOUNT_LOGIN,',
'       PREFERED_TZ,',
'       COUNTRY_CODE,',
'       country',
'     , DISCORD_ID',
'     , case when discord_id is not null then',
'        wmg_discord.avatar_link(p_discord_id => p.discord_id, p_avatar_uri => p.discord_avatar)',
'       else '''' end discord_profile',
'    , s.last_played',
'    , decode(ct.player_id, null, '''', ''Y'') signed_up_flag',
'  from WMG_PLAYERS_V p',
'     , stats s',
'     , current_tournament ct',
'where p.id = s.player_id (+)',
'  and p.id = ct.player_id (+)',
'  and p.id > 0'))
,p_header=>'<div id="selectedFacets"></div>'
,p_footer=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="pro-legend row margin-sm u-justify-content-space-around">',
'<div class="-wm-rank-elite fa margin-right-sm" title="Elite"> = Elite player</div>',
'<div class="-wm-rank-pro fa margin-right-sm" title="Pro"> = Pro</div>',
'<div class="-wm-rank-semi fa margin-right-sm" title="Semi-Pro"> = Semi-Pro</div>',
'<div class="-wm-rank-ama fa margin-right-sm" title="Amateur"> = Amateur player</div>',
'<div class="-wm-rank-new fa margin-right-sm" title="New player!"> = New player!</div>',
'</div>'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
