wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(47017731771573128492)
,p_name=>'P9_COURSE_ID'
,p_source_data_type=>'NUMBER'
,p_is_required=>true
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_imp.id(47017731107246128491)
,p_item_source_plug_id=>wwv_flow_imp.id(47017731107246128491)
,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P9_WHAT_IF is null then',
'  return apex_util.get_preference(''ROUND_COURSE_ID'');',
'else',
'  return :P9_COURSE_ID;',
'end if;'))
,p_item_default_type=>'FUNCTION_BODY'
,p_item_default_language=>'PLSQL'
,p_prompt=>'Course'
,p_source=>'COURSE_ID'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select prepared_name d, course_id r',
'from wmg_courses_v',
'where course_id in (',
'    select course_id',
'    from wmg_tournament_courses',
'    where tournament_session_id  in (',
'        select id',
'        from wmg_tournament_sessions',
'        where week= :P9_WEEK',
'    )',
')',
'or (:P9_WEEK = ''S00W00'' and :P9_PLAYERS_ID = 0)',
'or (:P9_WHAT_IF = ''Y'')',
'order by release_order, case when course_mode = ''E'' then 1 else 2 end'))
,p_lov_cascade_parent_items=>'P9_WEEK'
,p_ajax_optimize_refresh=>'Y'
