wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(50460422594043429769)
,p_event_id=>wwv_flow_imp.id(50460422511885429768)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' r wmg_rounds.id%type;',
' s1 wmg_rounds.s1%type;',
'begin',
'  if  :P9_PLAYERS_ID is null or :P9_WEEK is null then',
'    :P9_DUP_IND := ''N'';',
'  else',
'    select id, s1',
'      into r, s1',
'      from wmg_rounds',
'     where week = :P9_WEEK',
'       and course_id = :P9_COURSE_ID',
'       and players_id = :P9_PLAYERS_ID;',
'',
'    if s1 is not null then',
'      :P9_DUP_IND := ''Y'';',
'    else',
'      :P9_DUP_IND := ''R'';',
'      :P9_PREV_ID := r;',
'    end if;',
'  end if;',
'exception',
'when NO_DATA_FOUND then',
'  :P9_DUP_IND := ''N'';',
'end;',
''))
,p_attribute_02=>'P9_PLAYERS_ID,P9_WEEK,P9_DUP_IND,P9_COURSE_ID'
,p_attribute_03=>'P9_DUP_IND,P9_PREV_ID'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
