wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(24766716121675008563)
,p_name=>'Time Slots'
,p_region_name=>'slotsRegion'
,p_parent_plug_id=>wwv_flow_imp.id(57238785061911320950)
,p_template=>wwv_flow_imp.id(47017496920405127346)
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight:t-Report--hideNoPagination'
,p_grid_column_span=>10
,p_display_column=>2
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with tz as (',
'select :P30_TZ tz from dual',
')',
', slots_n as (',
'    select level n',
'     from dual',
'     connect by level <= 6',
'    )',
', slots as (',
'    select day_offset, slot || '':00'' d, slot t',
'    from (',
'        select lpad( (n-1)*4,2,0) slot, 0 day_offset',
'        from slots_n',
'        union all',
'        select ''22'' slot, -1 day_offset from dual',
'        union all',
'        select ''02'' slot, 0 day_offset from dual',
'        union all',
'        select ''06'' slot, 0 day_offset from dual',
'        union all',
'        select ''18'' slot, 0 day_offset from dual',
'    )',
')',
', ts as (',
'    select s.session_date',
'    from wmg_tournament_sessions s',
'    where s.tournament_id in (',
'        select id',
'          from wmg_tournaments',
'         where current_flag = ''Y''',
'    )',
'      and s.completed_ind = ''N''',
'      and (s.open_registration_on is null or s.open_registration_on < localtimestamp)',
'    order by s.session_date',
'    fetch first 1 rows only',
')',
'select selection',
'     , slot',
'     , t',
'     , utc',
'     , to_char(local_tz, ''fmDay, fmMonth fmDD'') ',
'      || '' at '' ',
'      || case when tz like ''US/%'' or tz like ''America%'' then',
'           ltrim(to_char(local_tz, ''HH:MI PM''), ''0'')',
'         else ',
'           to_char(local_tz, ''HH24:MI'')',
'         end local_tz',
'from (',
'select APEX_ITEM.RADIOGROUP(',
'      p_idx              => 1',
'    , p_value            => slots.d',
'    , p_attributes       => ''class="slotOption" data-slot="'' || slots.d || ''"''',
'    , p_selected_value   => decode(slots.d, s.time_slot, slots.d, '''')) selection',
'    , slots.d slot',
'    , slots.t',
'    , slots.day_offset',
'    , tz.tz',
'    , to_utc_timestamp_tz(to_char(s.session_date + slots.day_offset, ''yyyy-mm-dd'') || ''T'' || slots.t || '':00'') UTC',
'    , to_utc_timestamp_tz(to_char(s.session_date + slots.day_offset, ''yyyy-mm-dd'') || ''T'' || slots.t || '':00'') at time zone tz.tz local_tz',
'from ts s',
'   , tz',
'   , slots',
'   , (select time_slot from wmg_tournament_players tp where tp.tournament_session_id = :G_CURRENT_SESSION_ID and tp.player_id = :P30_PLAYER_ID and tp.active_ind = ''Y'') s',
'where slots.d = s.time_slot (+)',
')',
'order by day_offset, t',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P30_TZ,P30_PLAYER_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
