wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(53028239232517459343)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Signup/Unregister'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_rank_code    wmg_players_v.rank_code%type;',
'begin',
'',
'if :REQUEST = ''UNREGISTER'' then',
'  :G_ENROLLED_IND := ''N'';',
'  :G_REGISTRATION_ID := null;',
'  -- if the player is unregistering, remove their voites.',
'  -- this is the unix.dude because he was sneaky',
'  delete from wmg_course_vote where player_id = :P30_PLAYER_ID;',
'  if :P30_PLAYER_ID = :G_PLAYER_ID then',
'     :G_VOTING_ALLOWED := ''NO'';',
'  end if;',
'else ',
'  :G_ENROLLED_IND := ''Y'';',
'end if;',
'',
'merge into wmg_tournament_players p',
' using (',
'   select :G_CURRENT_SESSION_ID tournament_session_id',
'        , :P30_PLAYER_ID player_id',
'        , decode(:REQUEST, ''UNREGISTER'', ''N'', ''Y'') active_ind',
'        , apex_application.g_f01(1) time_slot',
'     from dual',
'  ) np',
' on (p.tournament_session_id = np.tournament_session_id',
'  and p.player_id = np.player_id',
' )',
'when matched then',
'  update',
'     set time_slot = np.time_slot',
'       , active_ind = np.active_ind',
'       , source = ''WEB''',
'when not matched then',
'  insert (',
'      tournament_session_id',
'    , player_id',
'    , time_slot',
'    , source',
'    , active_ind',
'  )',
'  values (',
'      :G_CURRENT_SESSION_ID',
'    , :P30_PLAYER_ID',
'    , apex_application.g_f01(1)',
'    , ''WEB''',
'    , :P30_ACTIVE_IND',
'  );',
'',
'if :REQUEST = ''SIGNUP'' and :G_REGISTRATION_ID is null then',
'  begin',
'    select tp.id',
'         , p.rank_code',
'      into :G_REGISTRATION_ID',
'         , l_rank_code',
'    from wmg_tournament_players tp',
'       , wmg_players_v p',
'    where tp.player_id = p.id',
'      and tp.tournament_session_id = :G_CURRENT_SESSION_ID',
'      and p.id = :P30_PLAYER_ID',
'      and tp.active_ind = ''Y'';',
'',
'    -- allow the player to vote in this session righ away',
'    :G_VOTING_ALLOWED := ''YES'';',
'   exception',
'    when no_data_found then',
'      -- this should not happen but lets protect',
'      :G_REGISTRATION_ID := null;',
'   end;',
'',
'   if l_rank_code = ''NEW'' then',
'       :P30_NEW_PLAYER_FLAG := ''Y'';',
'       wmg_notification.new_player(',
'          p_player_id => :P30_PLAYER_ID',
'        , p_registration_id => :G_REGISTRATION_ID',
'      );',
'',
'    end if;',
'',
'end if;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Signed-up processed!'
,p_internal_uid=>53005782939654846340
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2347727122378518546)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Remember Me'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_player_id wmg_players.id%type;',
'begin',
'    begin',
'        select id',
'          into l_player_id',
'          from wmg_players',
'         where account_login = :APP_USER',
'         fetch first 1 rows only;',
'    exception',
'      when NO_DATA_FOUND then',
'        l_player_id := null;',
'    end;',
'',
'    if :P30_PLAYER_ID = l_player_id or l_player_id is null then',
'        update wmg_players',
'          set account_login = :APP_USER',
'            , prefered_tz = :P30_TZ',
'        where id = :P30_PLAYER_ID;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'P30_REMEMBER_ME_IND'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_process_when2=>'Y'
,p_security_scheme=>'!'||wwv_flow_imp.id(47017660094734127428)
,p_internal_uid=>2325270829515905543
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2347727250995518547)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'init'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'if :G_REGISTRATION_ID is not null then',
'    select tp.player_id',
'         , case ',
'             when (p.account_login = :APP_USER or p.discord_id = :G_DISCORD_ID) then ''Y'' else ''N''',
'           end remeber_me',
'         , p.prefered_tz',
'      into :P30_PLAYER_ID',
'         , :P30_REMEMBER_ME_IND',
'         , :P30_TZ',
'    from wmg_tournament_players tp',
'       , wmg_players p',
'    where tp.player_id = p.id',
'      and tp.id = :G_REGISTRATION_ID;',
'else',
'    select p.id player_id',
'         , case ',
'             when (p.account_login = :APP_USER or p.discord_id = :G_DISCORD_ID) then ''Y'' else ''N''',
'           end remeber_me',
'         , p.prefered_tz',
'      into :P30_PLAYER_ID',
'         , :P30_REMEMBER_ME_IND',
'         , :P30_TZ',
'    from wmg_players p',
'   where (lower(p.account_login) = lower(:APP_USER)',
'       or p.discord_id = :G_DISCORD_ID',
'    )',
'    fetch first 1 rows only;',
'',
'',
'end if;',
'',
'exception',
'when NO_DATA_FOUND then',
'  if :APP_USER <> ''nobody'' then',
'   :P30_REMEMBER_ME_IND := ''Y'';',
'  end if;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>2325270958132905544
);
end;
