 p_id=>wwv_flow_imp.id(51705261776080345)
,p_name=>'22:00'
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_template_options=>'#DEFAULT#:t-Region--accent1:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlightOff:t-Report--noBorders:t-Report--hideNoPagination'
,p_grid_column_css_classes=>'room col-xxs-12 col-xs-12 col-sm-4 col-md-3'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select case when s.rooms_open_flag = ''Y'' or :P40_TD_FLAG = ''Y'' then nvl2(p.room_no, ''WMGT'', '''') || p.room_no else '''' end room_no',
'     , case when p.player_id = :G_PLAYER_ID then',
'        ''<mark class="player">''',
'       end',
'    || case when s.rooms_open_flag = ''Y'' or s.rooms_defined_flag = ''Y'' then '''' else row_number() over (order by p.tournament_player_id) || '': '' end',
'    || case when :P40_SHOW_AVATARS_IND = ''Y'' then  wmg_discord.avatar_link(p_discord_id => p.discord_id) end ',
'    || case when (s.rooms_defined_flag is null and p.player_id = :G_PLAYER_ID) or :P40_TD_FLAG = ''Y'' then',
'        '' <a href="'' ||',
'          apex_page.get_url(',
'              p_page => 30',
'            , p_items => ''P30_PLAYER_ID,P30_PAGE_ID_PREV''',
'            , p_values => p.player_id || '','' || :APP_PAGE_ID',
'          ) || ''">'' ',
'       end',
'    || apex_escape.html(p.player_name)',
'    || case when (s.rooms_defined_flag is null and p.player_id = :G_PLAYER_ID) or :P40_TD_FLAG = ''Y'' then ''</a>'' end',
'    || case when p.player_id = :G_PLAYER_ID then',
'        ''</mark>''',
'       end',
'    || case when p.rank_code = ''NEW'' then ''<span class="'' || p.rank_list_class || '' tooltip" title="'' || p.rank_name || ''"></span>'' end ',
'    || case when tp.team_id is not null then',
'     -- '' <span class="cgabadge u-pullRight tooltip" title="Team '' || tp.team_name || ''"></span>'' ',
'          ''<img class="u-pullRight teamLogo tooltip" title="Team '' || tp.team_name || ''" src="'' || apex_util.get_blob_file_src(''P571_TEAM_LOGO'', tp.team_id) || ''">'' end',
'    as players',
'from wmg_tournament_player_v p',
'   , wmg_tournament_sessions s',
'   , wmg_team_players_v tp',
'where s.id =  p.tournament_session_id',
'  and s.tournament_id = tp.tournament_id(+)',
'  and p.player_id = tp.player_id(+)',
'  and p.time_slot = ''22:00''',
'  and p.active_ind = ''Y''',
'  and p.tournament_session_id = :G_CURRENT_SESSION_ID',
'order by case when s.rooms_open_flag = ''Y'' or :P40_TD_FLAG = ''Y'' then',
'           p.room_no ',
'         else 0 end, p.tournament_player_id',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P40_TD_FLAG,P40_SHOW_AVATARS_IND'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_headings_type=>'NO_HEADINGS'
,p_query_num_rows=>200
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_break_cols=>'1'
,p_break_before_row=>'<hr>'
,p_break_generic_column=>'WMGT #ROOM_NO#'
,p_break_type_flag=>'REPEAT_HEADINGS_ON_BREAK_1'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
