'        '' <a href="'' ||',
'          apex_page.get_url(',
'              p_page => 30',
'            , p_items => ''P30_PLAYER_ID,P30_PAGE_ID_PREV''',
'            , p_values => p.player_id || '','' || :APP_PAGE_ID',
'          ) || ''">'' ',
'       end',
'    || apex_escape.html(p.player_name)',
'    || case when (s.rooms_defined_flag is null and p.player_id = :G_PLAYER_ID) or :P40_TD_FLAG = ''Y'' then ''</a>'' end',
'    || case when p.player_id = :G_PLAYER_ID then',
'        ''</mark>''',
'       end',
'    || case when p.rank_code = ''NEW'' then ''<span class="'' || p.rank_list_class || '' tooltip" title="'' || p.rank_name || ''"></span>'' end',
'    || case when tp.team_id is not null then',
'     -- '' <span class="cgabadge u-pullRight tooltip" title="Team '' || tp.team_name || ''"></span>'' ',
