,p_name=>'Next Tournament'
,p_template=>wwv_flow_imp.id(47017491752572127343)
,p_display_sequence=>5
,p_region_template_options=>'#DEFAULT#:t-Alert--colorBG:t-Alert--horizontal:t-Alert--noIcon:t-Alert--info'
,p_component_template_options=>'#DEFAULT#:t-Report--staticRowColors:t-Report--rowHighlightOff:t-Report--noBorders'
,p_grid_column_span=>6
,p_display_column=>4
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select s.session_date - 1 session_date',
'     , s.easy_course_code, nvl(ec.name, ''TBD -'') easy_course',
'     , s.hard_course_code, nvl(hc.name, ''TBD -'') hard_course',
'     , (select count(*) from wmg_tournament_players p where p.tournament_session_id = s.tournament_session_id and p.active_ind = ''Y'') players',
'from wmg_tournament_sessions_v s',
'   , wmg_courses ec',
'   , wmg_courses hc',
'where s.easy_course_id = ec.id (+)',
'  and s.hard_course_id = hc.id (+)',
'  and s.tournament_session_id = :G_CURRENT_SESSION_ID',
'/*',
'  and s.tournament_id in (',
'    select id',
'      from wmg_tournaments',
'     where current_flag = ''Y''',
')',
'and session_date+1 > sysdate',
'*/',
'order by s.session_date',
'fetch first 1 rows only'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_headings_type=>'NO_HEADINGS'
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>wwv_flow_string.join(wwv_flow_t_varchar2(
'- The next tournament courses have not been selected yet -<br>',
'Try again tomorrow...'))
,p_csv_output=>'N'
,p_prn_output=>'N'
