prompt --application/pages/page_00042
begin
wwv_flow_imp_page.create_page(
 p_id=>42
,p_name=>'Change Rooms'
,p_alias=>'CHANGE-ROOMS'
,p_page_mode=>'MODAL'
,p_step_title=>'Change Rooms'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#:ui-dialog--stretch'
,p_required_role=>wwv_flow_imp.id(55924489519682106951)
,p_protection_level=>'C'
,p_page_component_map=>'23'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(59216712876448937)
,p_plug_name=>'Rooms'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(47017504084872127348)
,p_plug_display_sequence=>5
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with room as (',
'select nvl2(p.room_no, ''WMGT'', '''') || p.room_no room_no',
'     , ''<div class="p" data-id='' || p.tournament_player_id || ''>'' ',
'    -- || row_number() over (partition by p.room_no order by p.tournament_player_id) || '': ''',
'    || apex_escape.html(p.player_name) ',
'    || case when p.rank_code = ''NEW'' then ''<span class="'' || p.rank_list_class || '' tooltip" title="'' || p.rank_name || ''"></span>'' end',
'    || ''</div>'' players',
'from wmg_tournament_player_v p',
'   , wmg_tournament_sessions s',
'where s.id =  p.tournament_session_id',
'  and p.time_slot = :P42_SLOT',
'  and p.active_ind = ''Y''',
'  and p.tournament_session_id = :G_CURRENT_SESSION_ID',
')',
'select room_no, listagg(players, chr(13)||chr(10)) players',
'from room',
'group by room_no',
'order by room_no',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P42_SLOT'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
