wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(105713191740039447)
,p_process_sequence=>30
,p_parent_process_id=>wwv_flow_imp.id(58509253488788843)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Automatic Verification'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_result wmg_verification_engine.verification_result_rec;',
'begin',
'    wmg_verification_engine.verify_player(',
'        p_tournament_session_id => :G_CURRENT_SESSION_ID',
'      , p_player_id             => :P50_PLAYERS_ID',
'      , p_room_name             => :P50_ROOM_NAME',
'      , x_verification_result   => l_result',
'    );',
'',
'    logger.log(''.. l_result.tournament_session_id:'' || l_result.tournament_session_id);',
'    logger.log(''.. l_result.room_no:'' || l_result.room_no);',
'    logger.log(''.. l_result.player_id:'' || l_result.player_id);',
'    logger.log(''.. l_result.card_run_id:'' || l_result.card_run_id);',
'    logger.log(''.. l_result.verification_status:'' || l_result.verification_status);',
'    logger.log(''.. l_result.mismatch_details:'' || l_result.mismatch_details);',
'',
'    if l_result.verification_status = ''SUCCESS'' and :G_PLAYER_ID is not null then',
'        wmg_verification_engine.update_verification_status(',
'            p_tournament_session_id => :G_CURRENT_SESSION_ID',
'          , p_player_id             => :G_PLAYER_ID',
'          , p_verified_flag         => ''Y''',
'        );',
'    end if;',
'exception',
'  when others then',
'    logger.log_error(''Unexpected error during verification'');    ',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'G_PLAYER_ID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>105713191740039447
,p_process_comment=>'This is the automatic verification of scorecards against the imported AI cards.'
);
end;
