'.hide_nav_pre .t-Form-itemText--pre {display: none;}',
'',
'#raceRegion {',
'    --ut-report-cell-padding-y: .35rem;',
'}',
'',
'@media (max-width: 639px) {',
'  #POS, td[headers="POS"] {',
'       --ut-report-cell-padding-x: .4rem;',
