wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(24533779410719036675)
,p_name=>'Most h1n Season &P60_TOURNAMENT.'
,p_parent_plug_id=>wwv_flow_imp.id(108375465883891787793)
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_new_grid_row=>false
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select r.*, rank() over (order by r.hn1 desc) pos',
'from (',
'    select substr(r.week,1,3) season',
'     , p.player_name',
'     , sum(r.score) hn1',
'  from wmg_rounds_unpivot_mv r',
'     , wmg_players_v p',
'     , wmg_courses c',
'where r.player_id = p.id',
'and c.id = r.course_id',
'and r.score = 1',
'and r.week in ( select week from wmg_tournament_sessions where tournament_id = :P61_TOURNAMENT_ID)',
'group by substr(r.week,1,3)',
'       , p.player_name',
'order by 3 desc',
') r',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>10
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
