wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(48859393294307903117)
,p_name=>'&P62_WEEK._ful_results.csv'
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with badges as (',
' select p.tournament_session_id, p.player_id',
'        -- need to expand by the badge_count, because people can habe multiple-badges',
'      , listagg( (select listagg(b.code, '' '') from dual connect by level <= p.badge_count) , '' '')  within group ( order by b.display_seq) other_badges',
'  from wmg_player_badges p',
'     , wmg_badge_types b',
'  where p.badge_type_code = b.code',
'--    and p.tournament_session_id = :P60_TOURNAMENT_SESSION_ID',
'    and b.selectable_ind = ''Y''',
'  group by p.tournament_session_id, p.player_id',
')',
'select ',
'  tp.pos',
', d.player_id',
', d.player_name',
', tp.points',
', d.rank_code',
', d.easy_code',
', d.hard_code',
', d.e1',
', d.e2',
', d.e3',
', d.e4',
', d.e5',
', d.e6',
', d.e7',
', d.e8',
', d.e9',
', d.e10',
', d.e11',
', d.e12',
', d.e13',
', d.e14',
', d.e15',
', d.e16',
', d.e17',
', d.e18',
', d.h1',
', d.h2',
', d.h3',
', d.h4',
', d.h5',
', d.h6',
', d.h7',
', d.h8',
', d.h9',
', d.h10',
', d.h11',
', d.h12',
', d.h13',
', d.h14',
', d.h15',
', d.h16',
', d.h17',
', d.h18',
', d.easy',
', d.hard',
', tp.total_score',
', nvl(p.issue_code, badges.other_badges) other_badges',
'from (',
'select week',
', player_id',
', player_name',
', rank_code',
', easy_course_code easy_code',
', hard_course_code hard_code',
', easy_s1 e1',
', easy_s2 e2',
', easy_s3 e3',
', easy_s4 e4',
', easy_s5 e5',
', easy_s6 e6',
', easy_s7 e7',
', easy_s8 e8',
', easy_s9 e9',
', easy_s10 e10',
', easy_s11 e11',
', easy_s12 e12',
', easy_s13 e13',
', easy_s14 e14',
', easy_s15 e15',
', easy_s16 e16',
', easy_s17 e17',
', easy_s18 e18',
', hard_s1 h1',
', hard_s2 h2',
', hard_s3 h3',
', hard_s4 h4',
', hard_s5 h5',
', hard_s6 h6',
', hard_s7 h7',
', hard_s8 h8',
', hard_s9 h9',
', hard_s10 h10',
', hard_s11 h11',
', hard_s12 h12',
', hard_s13 h13',
', hard_s14 h14',
', hard_s15 h15',
', hard_s16 h16',
', hard_s17 h17',
', hard_s18 h18',
', easy_par easy',
', hard_par hard',
'from (',
'  select r.week',
'       , r.player_id',
'       , r.player_name',
'       , r.rank_code',
'       , r.under_par',
'       , c.course_mode',
'       , c.code course_code',
'       , r.s1',
'       , r.s2',
'       , r.s3',
'       , r.s4',
'       , r.s5',
'       , r.s6',
'       , r.s7',
'       , r.s8',
'       , r.s9',
'       , r.s10',
'       , r.s11',
'       , r.s12',
'       , r.s13',
'       , r.s14',
'       , r.s15',
'       , r.s16',
'       , r.s17',
'       , r.s18',
'    from wmg_rounds_v r, wmg_courses c',
'  where r.course_id = c.id',
'     and r.week = :P62_WEEK',
'  )',
' pivot (',
'    sum(s1) s1 ',
'  , sum(s2) s2 ',
'  , sum(s3) s3 ',
'  , sum(s4) s4 ',
'  , sum(s5) s5 ',
'  , sum(s6) s6 ',
'  , sum(s7) s7 ',
'  , sum(s8) s8 ',
'  , sum(s9) s9 ',
'  , sum(s10) s10 ',
'  , sum(s11) s11 ',
'  , sum(s12) s12 ',
'  , sum(s13) s13 ',
'  , sum(s14) s14 ',
'  , sum(s15) s15 ',
'  , sum(s16) s16 ',
'  , sum(s17) s17 ',
'  , sum(s18) s18 ',
'  , sum(under_par) par ',
'  , any_value(course_code) course_code for course_mode in (',
'    ''E'' EASY, ''H'' HARD',
'   )',
'  )',
') d ',
', wmg_tournament_session_points_v tp',
', wmg_tournament_players p',
', badges',
'where tp.week = d.week',
'  and tp.player_id = d.player_id',
'  and tp.player_id = p.player_id',
'  and tp.tournament_session_id = p.tournament_session_id',
'  and tp.tournament_session_id = badges.tournament_session_id (+)',
'  and tp.player_id = badges.player_id (+)',
'order by tp.pos, tp.points, tp.player_name',
''))
,p_required_role=>wwv_flow_imp.id(47017660094734127428)
