prompt --application/pages/page_00075
begin
wwv_flow_imp_page.create_page(
 p_id=>75
,p_name=>'Verify Results'
,p_alias=>'VERIFY-RESULTS'
,p_step_title=>'Verify Results'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_file_urls=>'//cdnjs.cloudflare.com/ajax/libs/mark.js/8.11.1/jquery.mark.min.js'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function hasIssue(issueCode) {',
' var btn$ = $("button.is-active.js-menuButton").siblings(".wmg-action");',
' return btn$.data(''issue'') === issueCode;',
'}',
'',
'function verifyMenuAction(btn, actionMenu, issueCode, operation) {',
'     playerID = btn.dataset.id;',
'     apex.server.process(''SET_VERIFY_ISSUE''',
'    , {x01: playerID,',
'       x02: issueCode,',
'       x03: operation,',
'       pageItems: ''#P75_WEEK''',
'      }',
'    , {',
'        beforeSend: function(btn) {',
'          $(btn).parents("tr").find("[headers=''ACTIONS'']").append(''<span aria-hidden="true" class="fa fa-spinner fa-anim-spin"></span>'');',
'        },',
'        success: function( pData ) {',
'            var $cell = $(btn).parents("tr").find("[headers=''ACTIONS'']");',
'            if (pData.success) {',
'              $cell.find(".wmg-action button").addClass("t_button--primary"); //.append(''<i class="em '' + actionMenu.icon + ''" aria-role="presentation" aria-label="'' + actionMenu.icon + ''"></i>'');',
'              ',
'              apex.message.showPageSuccess( issueCode.toLowerCase() + " added!" );',
'              apex.region(''verifyRegion'').refresh();',
'              if (issueCode === "INFRACTION") {',
'                  $s("P75_NEW_FLAG", "E");',
'              }',
'              else {',
'                  $s("P75_NEW_FLAG", "");',
'              }',
'',
'',
'            }',
'            else {',
'                $cell.find("i." + actionMenu.icon).remove();',
'            }            ',
'            $cell.find(".fa-spinner").remove();',
'        }',
'    }',
' );',
'',
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var menu$ = $("<div id=''issue_list_menu''></div>");',
'$("body").append(menu$);',
'wmgt.theme.init();   ',
'menu$.menu({',
'  iconType: "em",',
'  items: [',
'    {',
'      type: "action",',
'      label: "No show",',
'      icon: "em-ghost",',
'      action: function(menu, btn) {',
'        // console.log("Adding", button$.data("id"));',
'        // console.log(this);',
'        verifyMenuAction(btn, this, ''NOSHOW'', ''S'');',
'        ',
'      },',
'      hide: function () {',
'          return hasIssue(''NOSHOW'');',
'      }',
'    },',
'    {',
'      type: "action",',
'      label: "No scores",',
'      icon: "em-x",',
'      action: function(menu, btn) {',
'        // console.log("Adding", button$.data("id"));',
'        // console.log(this);',
'        verifyMenuAction(btn, this, ''NOSCORE'', ''S'');',
'        ',
'      },',
'      hide: function () {',
'          return hasIssue(''NOSCORE'');',
'      }',
'    },',
'    {',
'      type: "action",',
'      label: "Rule Violation",',
'      icon: "em-red_circle",',
'      action: function(menu, btn) {',
'        // console.log("Adding", button$.data("id"));',
'        // console.log(this);',
'        verifyMenuAction(btn, this, ''INFRACTION'', ''S'');',
'        ',
'      },',
'      hide: function () {',
'          return hasIssue(''INFRACTION'');',
'      }',
'    },',
'  ]',
'});',
''))
,p_css_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'//emoji-css.afeld.me/emoji.css',
'#APP_FILES#css/week-lov#MIN#.css'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.noshow, .verification, .roomVerification {cursor:pointer;}',
'.vYES {color: green;}',
'.vERROR {color: red;}',
'.vYES:before {content: "\f14a";}',
'.NA_:before,.vNO:before {content: "\f096";}',
'.vERROR:before {content: "\eb00";}',
'span.NA_Y:before {content: "\e9e5"; color: orange;font-weight: bold;}',
'',
'.vStatus {position: relative;}',
'.FAILED, .SUCCESS, .NO_MATCH {',
'    width: 8px;',
'    height: 8px;',
'    display: inline-block;',
'    position: absolute;',
'    top: -7px;',
'}',
'.NO_MATCH {',
'    background-color: var(--rw-palette-neutral-100);',
'}',
'.FAILED {',
'    background-color: var(--ut-palette-danger);',
