wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(34454357713307899)
,p_name=>'Verify Results'
,p_region_name=>'verifyRegion'
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>209
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--hideHeader:t-Region--scrollBody:margin-left-none'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline'
,p_new_grid_row=>false
,p_grid_column_span=>10
,p_grid_column_css_classes=>'padding-left-none  col-xxs-10 col-sm-11'
,p_display_column=>2
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with scorecards as (',
'  select p.week',
'       , r.pos',
'       , p.player_id',
'       , p.tournament_player_id',
'       , p.tournament_player_created',
'       , p.player_name',
'       , p.discord_id',
'       , p.time_slot',
'       , p.room_no',
'       , r.easy_par',
'       , r.hard_par',
'       , r.total_score',
'       , r.easy_round_id',
'       , r.hard_round_id',
'       , r.round_created_on',
'       , r.easy_scorecard',
'       , r.hard_scorecard',
'       , r.total_scorecard',
'       , p.rank_name',
'       , p.rank_list_class',
'       , p.rank_code',
'       , p.verified_score_flag',
'       , p.verified_note',
'       , p.verified_by',
'       , p.verified_on',
'       , p.issue_code',
'       , case ',
'             when p.issue_code is null then ''No show?''',
'             else i.name',
'          end action_label',
'       , i.icon action_icon',
'       , case when p.issue_code is not null then ''t-Button--primary'' else '''' end action_selected',
'       , r.easy_verification_status',
'       , r.hard_verification_status',
'    from wmg_tournament_results_v r',
'       , wmg_tournament_player_v p',
'       , wmg_issues i',
'   where p.week = r.week (+)',
'     and p.player_id = r.player_id (+)',
'     and p.week = :P75_WEEK',
'     and p.issue_code = i.code (+)',
'     and p.active_ind = ''Y''',
'     and (:P75_SLOT is null or :P75_SLOT = p.time_slot)',
'     and (:P75_ROOM is null or to_number(:P75_ROOM default null on conversion error) = p.room_no)',
')',
'select sc.pos',
'     , sc.time_slot',
'     , sc.room_no',
'     , sc.player_id',
'     , sc.tournament_player_id',
'     , sc.tournament_player_created',
'     , wmg_discord.avatar_link(p_discord_id => sc.discord_id) avatar',
'     , sc.player_name',
'     , sc.player_rank',
'     , sc.easy_scorecard',
'     , sc.hard_scorecard',
'     , sc.total_scorecard',
'     , sc.easy_round_id',
'     , sc.hard_round_id',
'     , sc.round_created_on',
'     , sc.easy_par',
'     , sc.hard_par',
'     , sc.total_score',
'     , sc.easy_diff',
'     , sc.hard_diff',
'     , sc.verification_class',
'     , sc.verified',
'     , sc.verified_score_flag',
'     , sc.verified_note',
'     , sc.verified_by',
'     , sc.verified_on',
'     , sc.issue_code',
'     , '''' actions',
'     , sc.action_selected',
'     , sc.action_label',
'     , sc.action_icon',
'     , sc.easy_verification_status',
'     , sc.hard_verification_status',
'from  (',
'    select s.pos',
'         , s.time_slot',
'         , s.room_no',
'         , s.player_id',
'         , s.discord_id',
'         , s.tournament_player_id',
'         , s.tournament_player_created',
'         , s.player_name',
'         , case when s.rank_code = ''NEW'' then ''<span class="'' || s.rank_list_class || '' tooltip" title="'' || s.rank_name || ''"></span>'' end player_rank',
'         , s.easy_scorecard',
'         , s.hard_scorecard',
'         , s.total_scorecard',
'         , s.easy_round_id',
'         , s.hard_round_id',
'         , s.round_created_on',
'         , s.easy_par',
'         , s.hard_par',
'         , s.total_score',
'         , case when (nvl(s.easy_scorecard, -999) != nvl(s.easy_par, -999)) then ''mark'' else '''' end easy_diff',
'         , case when (nvl(s.hard_scorecard, -999) != nvl(s.hard_par, -999)) then ''mark'' else '''' end hard_diff',
'         , case ',
'             when  s.easy_scorecard = s.easy_par',
'               and s.hard_scorecard = s.hard_par',
'               and s.total_scorecard = s.total_score',
'            then ',
'               ''Y''',
'             else ',
'               ''N''',
'             end verification_class',
'          , case ',
'               when (s.total_scorecard != s.total_score)',
'               then 1',
'               when pos is null then 3',
'               else 2 ',
'            end display_seq',
'          , decode(s.verified_score_flag, null, ''NO'', ''E'', ''ERROR'', ''YES'') verified',
'          , s.verified_score_flag',
'          , s.verified_note',
'          , s.verified_by',
'          , s.verified_on',
'          , s.issue_code',
'          , s.action_label',
'          , s.action_selected',
'          , s.action_icon',
'          , s.easy_verification_status',
'          , s.hard_verification_status',
'      from scorecards s',
') sc',
', wmg_time_slots_all_v t',
'where sc.time_slot = t.time_slot',
'  and (:P75_SHOW_NO_SHOWS_FLAG = ''N'' or (:P75_SHOW_NO_SHOWS_FLAG = ''Y'' and sc.issue_code = ''NOSHOW''))',
'  and (:P75_DIFF_ONLY_FLAG = ''N'' or (sc.verification_class = ''N'' or :P75_SHOW_NO_SHOWS_FLAG = ''Y'' ))',
'  and ((:P75_SHOW_MISSING_FLAG = ''N'' and sc.pos is not null) or :P75_SHOW_MISSING_FLAG = ''Y'')',
'  and (( :P75_SHOW_VERYFIED_FLAG = ''N'' and sc.verified_score_flag is null or :P75_SHOW_NO_SHOWS_FLAG = ''Y'') or (:P75_SHOW_VERYFIED_FLAG in (''Y'', ''E'') ))',
'order by t.day_offset, sc.time_slot, sc.room_no, sc.display_seq',
'   , sc.tournament_player_created',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P75_WEEK,P75_DIFF_ONLY_FLAG,P75_SHOW_MISSING_FLAG,P75_SHOW_VERYFIED_FLAG,P75_SHOW_NO_SHOWS_FLAG,P75_SLOT,P75_ROOM,P75_EASY,P75_HARD'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>200
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'no data found'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>500
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_prn_format=>'PDF'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
