,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlightOff:t-Report--hideNoPagination'
,p_grid_column_span=>1
,p_grid_column_css_classes=>'padding-right-none  col-xxs-2 col-sm-1'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select decode(:P75_SLOT, null, r.time_slot, null) split_group',
'     , r.id',
'     , r.time_slot',
'     , r.room_no',
'     , case when to_number(:P75_ROOM default null on conversion error) = r.room_no then ''is-current'' else '''' end current_class',
'     , decode(r.verified_score_flag, null, ''NO'', ''E'', ''ERROR'', ''YES'') verified',
'     , r.verified_score_flag',
'     , r.verified_by',
'     , r.verified_on',
'  from wmg_tournament_rooms r',
'     , wmg_time_slots_all_v t',
' where r.time_slot = t.time_slot',
'   and r.tournament_session_id = (select id from wmg_tournament_sessions where week = :P75_WEEK)',
'   and (:P75_SLOT is null or :P75_SLOT = r.time_slot)',
'order by t.day_offset, r.time_slot, r.room_no'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P75_WEEK,P75_ROOM,P75_SLOT'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
