wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(69389714908291615)
,p_event_id=>wwv_flow_imp.id(69389317685291611)
,p_event_result=>'TRUE'
,p_action_sequence=>50
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'  l_issue_code wmg_tournament_players.issue_code%type;',
'  l_operation varchar2(1);  -- (S)et | (C)lear',
'begin',
'  if :P75_ISSUE_CODE is null then -- when theres no issue_code we default to No Show',
'    l_issue_code := ''NOSHOW'';',
'    l_operation := ''S'';',
'  else',
'    l_issue_code := :P75_ISSUE_CODE;',
'    l_operation := ''C'';',
'  end if;',
'',
'  -- toggle the verification',
'  update wmg_tournament_players',
'   set issue_code = case',
'                         when l_operation = ''C'' then null',
'                         else l_issue_code',
'                      end',
'     , points_override = case',
'                         when l_operation = ''C'' then null',
'                       end',
'     , verified_score_flag = case when l_operation = ''C'' then null else ''Y'' end',
'     , verified_by         = case when l_operation = ''C'' then null else sys_context(''APEX$SESSION'',''APP_USER'') end',
'     , verified_on         = case when l_operation = ''C'' then null else current_timestamp end',
'     , verified_note       = ',
'        case when l_operation = ''C'' then null ',
'         else ',
'             case ',
'             when l_issue_code = ''NOSHOW'' then ''No show''',
'             when l_issue_code = ''NOSCORE'' then ''Score not entered on time''',
'             when l_issue_code = ''INFRACTION'' then ''Infraction''',
'             else null',
'             end',
'        end',
'    where id = :P75_ID;',
'',
'  -- Check if the room is all verified',
'  wmg_util.verify_players_room(p_tournament_player_id => :P75_ID);',
'',
'end;'))
,p_attribute_02=>'P75_ID,P75_ISSUE_CODE'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
