,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_name=>'Get Time Slot Local Time'
,p_action=>'NATIVE_SET_VALUE'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P75_LOCAL_TIME'
,p_attribute_01=>'SQL_STATEMENT'
,p_attribute_03=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select case ',
'        when local_tz is null then null ',
'        when sessiontimezone like ''US/%'' or sessiontimezone like ''America%'' then',
'           ltrim(to_char(local_tz, ''HH:MI PM''), ''0'') || '' local''',
'         else ',
'           to_char(local_tz, ''HH24:MI'') || '' local''',
'         end',
'       at_local_time',
'from (',
'select to_utc_timestamp_tz(to_char(s.session_date + ts.day_offset, ''yyyy-mm-dd'') || ''T'' || :P75_SLOT) at time zone sessiontimezone local_tz',
'from wmg_tournament_sessions s',
'   , wmg_time_slots_all_v ts',
'where s.id = :G_CURRENT_SESSION_ID',
'  and ts.time_slot = :P75_SLOT',
'union all',
'select null local_tz',
'from dual',
'where :P75_SLOT is null',
') r'))
,p_attribute_07=>'P75_SLOT'
,p_attribute_08=>'Y'
,p_attribute_09=>'N'
,p_wait_for_result=>'Y'
);
