wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(54919625773042434)
,p_chart_id=>wwv_flow_imp.id(54919552369042433)
,p_seq=>10
,p_name=>'Coconuts Lost'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with coconut as (',
'    select tc.tournament_session_id',
'         , tc.course_no',
'         , u.course_id',
'         , u.h',
'         , u.par',
'         , row_number() over (partition by u.player_id order by tc.course_no, u.h) rn',
'      from wmg_rounds_unpivot_mv u',
'         , wmg_tournament_sessions ts',
'         , wmg_tournament_courses tc',
'         , wmg_tournament_players tp',
'     where ts.week = u.week',
'       and ts.id = tp.tournament_session_id',
'       and ts.id = tc.tournament_session_id',
'       and tc.course_id = u.course_id',
'       and tp.player_id = u.player_id',
'       and u.week = :P100_WEEK',
'       and u.par > 0 -- coconut lost on a bogey',
'--       and u.player_id in (22, 24)',
'--     having sum(case when par <= 0 then 1 else 0 end) = 36',
'--     group by u.week, u.player_id',
'-- order by u.player_id, tc.course_no, u.h',
')',
', coconut_histogram as (',
'  select c.tournament_session_id',
'       , c.course_no',
'       , c.course_id',
'       , c.h',
'       , count(*) lost_coconut',
'    from coconut c',
'   where rn = 1  -- first time the coconut was lost',
'   group by c.tournament_session_id',
'       , c.course_no',
'       , c.course_id',
'       , c.h',
')',
', empty_holes as (',
'    select level h',
'    from dual',
'    connect by level <= 18',
')',
', fill_in_all_holes as (',
'select tc.tournament_session_id',
'     , tc.course_no',
'     , tc.course_id',
'     , e.h',
'     , nvl(h.lost_coconut, 0) lost_coconut',
' from coconut_histogram h',
'    , wmg_tournament_courses tc',
'    , wmg_tournament_sessions ts',
'    , empty_holes e',
'where ts.id = tc.tournament_session_id',
'  and ts.week = :P100_WEEK',
'  and tc.tournament_session_id = h.tournament_session_id (+)',
'  and tc.course_no = h.course_no (+)',
'  and tc.course_id = h.course_id (+)',
'  and e.h = h.h (+)',
')',
'select h.course_no',
'     , c.code course_code',
'     , e.h',
'     , h.course_no || '' '' || c.code || '' '' || e.h label',
'     , h.lost_coconut value',
'from fill_in_all_holes h',
'   , wmg_courses c',
'   , empty_holes e',
'where c.id = h.course_id',
'  and e.h = h.h (+)',
'order by h.course_no, h.h',
''))
,p_ajax_items_to_submit=>'P100_WEEK'
,p_items_value_column_name=>'VALUE'
,p_items_label_column_name=>'LABEL'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>true
,p_items_label_position=>'auto'
,p_items_label_display_as=>'PERCENT'
,p_threshold_display=>'onIndicator'
);
