wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(47664153231646126235)
,p_chart_id=>wwv_flow_imp.id(47664153169564126234)
,p_seq=>10
,p_name=>'Series 1'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with week_courses as (',
'  select id course_id, course_mode, :P100_WEEK week',
'    from wmg_courses',
'   where id in (',
'      select distinct course_id',
'        from wmg_rounds ',
'       where week = :P100_WEEK ',
'    )',
'   and course_mode = ''H''',
')',
'select ''Double Bogeys'' label',
'     , sum(decode(s1  - 2, h1, 1, 0)',
'         + decode(s2  - 2, h2, 1, 0)',
'         + decode(s3  - 2, h3, 1, 0)',
'         + decode(s4  - 2, h4, 1, 0)',
'         + decode(s5  - 2, h5, 1, 0)',
'         + decode(s6  - 2, h6, 1, 0)',
'         + decode(s7  - 2, h7, 1, 0)',
'         + decode(s8  - 2, h8, 1, 0)',
'         + decode(s9  - 2, h9, 1, 0)',
'         + decode(s10 - 2, h10, 1, 0)',
'         + decode(s11 - 2, h11, 1, 0)',
'         + decode(s12 - 2, h12, 1, 0)',
'         + decode(s13 - 2, h13, 1, 0)',
'         + decode(s14 - 2, h14, 1, 0)',
'         + decode(s15 - 2, h15, 1, 0)',
'         + decode(s16 - 2, h16, 1, 0)',
'         + decode(s17 - 2, h17, 1, 0)',
'         + decode(s18 - 2, h18, 1, 0)',
'       ) value',
'  from wmg_rounds_v r, week_courses w',
' where r.week = w.week',
'   and r.course_id = w.course_id',
'  group by w.course_mode',
'union all',
'select ''Bogeys'' label',
'     , sum(decode(s1  - 1, h1, 1, 0)',
'         + decode(s2  - 1, h2, 1, 0)',
'         + decode(s3  - 1, h3, 1, 0)',
'         + decode(s4  - 1, h4, 1, 0)',
'         + decode(s5  - 1, h5, 1, 0)',
'         + decode(s6  - 1, h6, 1, 0)',
'         + decode(s7  - 1, h7, 1, 0)',
'         + decode(s8  - 1, h8, 1, 0)',
'         + decode(s9  - 1, h9, 1, 0)',
'         + decode(s10 - 1, h10, 1, 0)',
'         + decode(s11 - 1, h11, 1, 0)',
'         + decode(s12 - 1, h12, 1, 0)',
'         + decode(s13 - 1, h13, 1, 0)',
'         + decode(s14 - 1, h14, 1, 0)',
'         + decode(s15 - 1, h15, 1, 0)',
'         + decode(s16 - 1, h16, 1, 0)',
'         + decode(s17 - 1, h17, 1, 0)',
'         + decode(s18 - 1, h18, 1, 0)',
'       ) value',
'  from wmg_rounds_v r, week_courses w',
' where r.week = w.week',
'   and r.course_id = w.course_id',
'  group by w.course_mode',
'union all',
'select ''Pars'' label',
'     , sum(decode(s1, h1, 1, 0)',
'         + decode(s2, h2, 1, 0)',
'         + decode(s3, h3, 1, 0)',
'         + decode(s4, h4, 1, 0)',
'         + decode(s5, h5, 1, 0)',
'         + decode(s6, h6, 1, 0)',
'         + decode(s7, h7, 1, 0)',
'         + decode(s8, h8, 1, 0)',
'         + decode(s9, h9, 1, 0)',
'         + decode(s10, h10, 1, 0)',
'         + decode(s11, h11, 1, 0)',
'         + decode(s12, h12, 1, 0)',
'         + decode(s13, h13, 1, 0)',
'         + decode(s14, h14, 1, 0)',
'         + decode(s15, h15, 1, 0)',
'         + decode(s16, h16, 1, 0)',
'         + decode(s17, h17, 1, 0)',
'         + decode(s18, h18, 1, 0)',
'     ) value',
'  from wmg_rounds_v r, week_courses w',
' where r.week = w.week',
'   and r.course_id = w.course_id',
'  group by w.course_mode',
'union all',
'select ''Aces'' label',
'     , sum(decode(s1, 1, 1, 0)',
'         + decode(s2, 1, 1, 0)',
'         + decode(s3, 1, 1, 0)',
'         + decode(s4, 1, 1, 0)',
'         + decode(s5, 1, 1, 0)',
'         + decode(s6, 1, 1, 0)',
'         + decode(s7, 1, 1, 0)',
'         + decode(s8, 1, 1, 0)',
'         + decode(s9, 1, 1, 0)',
'         + decode(s10, 1, 1, 0)',
'         + decode(s11, 1, 1, 0)',
'         + decode(s12, 1, 1, 0)',
'         + decode(s13, 1, 1, 0)',
'         + decode(s14, 1, 1, 0)',
'         + decode(s15, 1, 1, 0)',
'         + decode(s16, 1, 1, 0)',
'         + decode(s17, 1, 1, 0)',
'         + decode(s18, 1, 1, 0)',
'     ) value',
'  from wmg_rounds_v r, week_courses w',
' where r.week = w.week',
'   and r.course_id = w.course_id',
'  group by w.course_mode',
'union all',
'select ''Birdies'' label',
'     , sum(case when s1>1 and s1  + 1 = h1 then 1 else 0 end',
'         + case when s2>1 and s2  + 1 = h2 then 1 else 0 end',
'         + case when s3>1 and s3  + 1 = h3 then 1 else 0 end',
'         + case when s4>1 and s4  + 1 = h4 then 1 else 0 end',
'         + case when s5>1 and s5  + 1 = h5 then 1 else 0 end',
'         + case when s6>1 and s6  + 1 = h6 then 1 else 0 end',
'         + case when s7>1 and s7  + 1 = h7 then 1 else 0 end',
'         + case when s8>1 and s8  + 1 = h8 then 1 else 0 end',
'         + case when s9>1 and s9  + 1 = h9 then 1 else 0 end',
'         + case when s10>1 and s10 + 1 = h10 then 1 else 0 end',
'         + case when s11>1 and s11 + 1 = h11 then 1 else 0 end',
'         + case when s12>1 and s12 + 1 = h12 then 1 else 0 end',
'         + case when s13>1 and s13 + 1 = h13 then 1 else 0 end',
'         + case when s14>1 and s14 + 1 = h14 then 1 else 0 end',
'         + case when s15>1 and s15 + 1 = h15 then 1 else 0 end',
'         + case when s16>1 and s16 + 1 = h16 then 1 else 0 end',
'         + case when s17>1 and s17 + 1 = h17 then 1 else 0 end',
'         + case when s18>1 and s18 + 1 = h18 then 1 else 0 end',
'     ) value',
'  from wmg_rounds_v r, week_courses w',
' where r.week = w.week',
'   and r.course_id = w.course_id',
'  group by w.course_mode',
'union all',
'select ''Eagles'' label',
'  , sum(case when s1>1 and s1  + 2 = h1 then 1 else 0 end',
'      + case when s2>1 and s2  + 2 = h2 then 1 else 0 end',
'      + case when s3>1 and s3  + 2 = h3 then 1 else 0 end',
'      + case when s4>1 and s4  + 2 = h4 then 1 else 0 end',
'      + case when s5>1 and s5  + 2 = h5 then 1 else 0 end',
'      + case when s6>1 and s6  + 2 = h6 then 1 else 0 end',
'      + case when s7>1 and s7  + 2 = h7 then 1 else 0 end',
'      + case when s8>1 and s8  + 2 = h8 then 1 else 0 end',
'      + case when s9>1 and s9  + 2 = h9 then 1 else 0 end',
'      + case when s10>1 and s10 + 2 = h10 then 1 else 0 end',
'      + case when s11>1 and s11 + 2 = h11 then 1 else 0 end',
'      + case when s12>1 and s12 + 2 = h12 then 1 else 0 end',
'      + case when s13>1 and s13 + 2 = h13 then 1 else 0 end',
'      + case when s14>1 and s14 + 2 = h14 then 1 else 0 end',
'      + case when s15>1 and s15 + 2 = h15 then 1 else 0 end',
'      + case when s16>1 and s16 + 2 = h16 then 1 else 0 end',
'      + case when s17>1 and s17 + 2 = h17 then 1 else 0 end',
'      + case when s18>1 and s18 + 2 = h18 then 1 else 0 end',
'   ) value',
' from wmg_rounds_v r, week_courses w',
'where r.week = w.week',
'and r.course_id = w.course_id',
'union all',
'select ''Albatrosses'' label',
'  , sum(case when s1>1 and s1  + 3 = h1 then 1 else 0 end',
'      + case when s2>1 and s2  + 3 = h2 then 1 else 0 end',
'      + case when s3>1 and s3  + 3 = h3 then 1 else 0 end',
'      + case when s4>1 and s4  + 3 = h4 then 1 else 0 end',
'      + case when s5>1 and s5  + 3 = h5 then 1 else 0 end',
'      + case when s6>1 and s6  + 3 = h6 then 1 else 0 end',
'      + case when s7>1 and s7  + 3 = h7 then 1 else 0 end',
'      + case when s8>1 and s8  + 3 = h8 then 1 else 0 end',
'      + case when s9>1 and s9  + 3 = h9 then 1 else 0 end',
'      + case when s10>1 and s10 + 3 = h10 then 1 else 0 end',
'      + case when s11>1 and s11 + 3 = h11 then 1 else 0 end',
'      + case when s12>1 and s12 + 3 = h12 then 1 else 0 end',
'      + case when s13>1 and s13 + 3 = h13 then 1 else 0 end',
'      + case when s14>1 and s14 + 3 = h14 then 1 else 0 end',
'      + case when s15>1 and s15 + 3 = h15 then 1 else 0 end',
'      + case when s16>1 and s16 + 3 = h16 then 1 else 0 end',
'      + case when s17>1 and s17 + 3 = h17 then 1 else 0 end',
'      + case when s18>1 and s18 + 3 = h18 then 1 else 0 end',
'   ) value',
'from wmg_rounds_v r, week_courses w',
'where r.week = w.week',
'and r.course_id = w.course_id',
''))
,p_max_row_count=>20
,p_items_value_column_name=>'VALUE'
