wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(47608384199425082235)
,p_name=>'Course Highlights'
,p_parent_plug_id=>wwv_flow_imp.id(49336628163656201542)
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>40
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight:t-Report--horizontalBorders'
,p_new_grid_row=>false
,p_grid_column_css_classes=>'col-sm-8 col-md-8 col-lg-12'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with base_course_unpivot as (',
'   select week, course_id, course_code, course_mode, course_name, h, score, par',
'    from wmg_rounds_v',
'    unpivot (',
'      (score, par) for h in (',
'      (s1, par1) as 1,',
'      (s2, par2) as 2,',
'      (s3, par3) as 3,',
'      (s4, par4) as 4,',
'      (s5, par5) as 5,',
'      (s6, par6) as 6,',
'      (s7, par7) as 7,',
'      (s8, par8) as 8,',
'      (s9, par9) as 9,',
'      (s10, par10) as 10,',
'      (s11, par11) as 11,',
'      (s12, par12) as 12,',
'      (s13, par13) as 13,',
'      (s14, par14) as 14,',
'      (s15, par15) as 15,',
'      (s16, par16) as 16,',
'      (s17, par17) as 17,',
'      (s18, par18) as 18',
'      )',
'    )',
'  where week = :P100_WEEK',
'--    and tc.tournament_session_id = :P100_TOURNAMENT_SESSION_ID',
')',
', course_unpivot as (',
'  select tc.tournament_session_id, u.week, tc.course_id, u.course_code, u.course_mode, tc.course_no, u.course_name, u.h, u.score, u.par',
'    from base_course_unpivot u',
'       , wmg_tournament_courses tc',
'  where tc.course_id = u.course_id',
'   and tc.tournament_session_id = :P100_TOURNAMENT_SESSION_ID',
')',
', whole_totals as (',
'      select course_no, course_id, course_code, course_mode, h, sum(score) total',
'        from course_unpivot',
'       group by course_no, course_id, course_code, course_mode, h',
')',
', whole_pars as (',
'      select course_no, course_id, course_code, course_mode, h, sum(par) total',
'        from course_unpivot',
'       group by course_no, course_id, course_code, course_mode,  h',
')',
'select ''Tournament Strokes'' highlight, ''Both Courses'' what, sum(total) total',
'  from whole_totals',
'union all',
'select ''Hole with most Aces''',
'     , ''<a href="javascript:viewH2('''''' || course_no || '''''','' || h || '')">'' ',
'      || course_code || '' - H'' || to_char(h) || ''</a>'' what',
'     , total',
'from ( ',
'       select course_no, course_code, h, sum(score) total',
'        from course_unpivot',
'       where score = 1',
'       group by course_no, course_code, h',
'       order by total desc',
'       fetch first 1 rows only',
')',
'union all',
'select ''Easiest hole (strokes)''',
'     , ''<a href="javascript:viewH2('''''' || course_no || '''''','' || h || '')">'' ',
'     -- || apex_page.get_url(p_page => 15, p_items => ''P15_COURSE_ID,P15_HOLE'', p_values => course_id || '','' || h) || ''">''',
'      || course_code || '' - H'' || to_char(h) || ''</a>'' what',
'     , total',
'from ( ',
'       select course_no, course_code, h, total',
'        from whole_totals',
'       order by total',
'       fetch first 1 rows only',
')',
'union all',
'select ''Most difficult hole (strokes)''',
'     , ''<a href="javascript:viewH2('''''' || course_no || '''''','' || h || '')">'' ',
'      || course_code || '' - H'' || to_char(h) || ''</a>'' what',
'     , total',
'from ( ',
'       select course_no, course_code, h, total',
'        from whole_totals',
'       order by total desc',
'       fetch first 1 rows only',
')',
'union all',
'select ''Most difficult hole (Over Par)''',
'     , ''<a href="javascript:viewH2('''''' || course_no || '''''','' || h || '')">'' ',
'      || course_code || '' - H'' || to_char(h) || ''</a>'' what',
'     , total',
'from ( ',
'       select course_no, course_code, h, total',
'        from whole_pars',
'       order by total desc',
'       fetch first 1 rows only',
')',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P100_WEEK,P100_TOURNAMENT_SESSION_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
