wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(49336627225391201533)
,p_name=>'Top Players'
,p_parent_plug_id=>wwv_flow_imp.id(49336628163656201542)
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:i-h240:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody:margin-bottom-md'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight:t-Report--horizontalBorders'
,p_grid_column_css_classes=>'col-sm-8 col-md-6 col-lg-7'
,p_display_point=>'SUB_REGIONS'
,p_item_display_point=>'BELOW'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with coconut as (',
'    select u.week',
'         , u.player_id, sum(case when par <= 0 then 1 else 0 end) under_par',
'         , sum(case when score = 1 then 1 else 0 end) hn1_count',
'      from wmg_rounds_unpivot_mv u',
'         , wmg_tournament_sessions ts',
'     where ts.week = u.week',
'         and u.week = :P100_WEEK',
'         and ts.completed_ind = ''N''',
'     having sum(case when par <= 0 and score is not null then 1 else 0 end) = 36',
'     group by u.week, u.player_id',
')',
', cactus as (',
'     select player_id, count(*) n',
'      from (',
'      select u.course_id || '':'' || u.h h, u.score, any_value(u.player_id) player_id',
'        from wmg_rounds_unpivot_mv u',
'           , wmg_tournament_sessions ts',
'       where ts.week = u.week',
'         and u.week = :P100_WEEK',
'         and ts.completed_ind = ''N''',
'         and u.score = 1',
'      having count(*) = 1',
'       group by u.course_id || '':'' || u.h, u.score',
'     )',
'     group by player_id',
')',
', badges as (',
' select p.tournament_session_id, p.player_id',
'        -- need to expand by the badge_count, because people can habe multiple-badges',
'      , listagg( (select listagg(replace(b.icon_class, ''em em'', ''em''), '' '') from dual connect by level <= p.badge_count) , '' '')  within group ( order by b.display_seq) other_badges',
'  from wmg_player_badges p',
'     , wmg_badge_types b',
'  where p.badge_type_code = b.code',
'    and p.tournament_session_id = :P100_TOURNAMENT_SESSION_ID',
'    and b.selectable_ind = ''Y''',
'  group by p.tournament_session_id, p.player_id',
')',
'select r.*, rank() over (order by r.total_score) pos',
'     , decode(r.player_id, :G_PLAYER_ID, ''mark'', '''') selected_player',
'     , decode(coconut.under_par, 36, ''em-coconut'' || decode(cactus.player_id, null, '''', '' ''), '''')',
'    || decode(cactus.player_id, null, null,  (select listagg(''em-cactus'', '' '') from dual connect by level <= cactus.n) )',
'    || badges.other_badges badges',
'from (',
'  select player_id, player_name, country_code, easy, hard',
'       , easy + hard total_score',
'  from (',
'    select r.player_id, r.player_name, r.country_code',
'         , r.under_par',
'         , tc.course_no',
'      from wmg_rounds_v r',
'         , wmg_courses c',
'         , wmg_tournament_courses tc',
'     where tc.tournament_session_id = r.tournament_session_id',
'       and tc.course_id = c.id',
'       and tc.tournament_session_id = :P100_TOURNAMENT_SESSION_ID',
'       and r.course_id = c.id',
'    )',
'   pivot (',
'     sum(under_par) for course_no in (',
'      1 EASY, 2 HARD',
'     )',
'    )',
') r',
', coconut',
', cactus',
', badges',
'where r.player_id = coconut.player_id (+)',
'  and r.player_id = cactus.player_id (+)',
'  and r.player_id = badges.player_id (+)',
'order by pos, r.player_name',
'fetch first 15 rows only',
''))
,p_ajax_enabled=>'Y'
