wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(49336627648861201537)
,p_name=>'Highlights'
,p_parent_plug_id=>wwv_flow_imp.id(49336628163656201542)
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody:margin-left-md:margin-right-md'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight:t-Report--horizontalBorders'
,p_new_grid_row=>false
,p_grid_column_css_classes=>'col-sm-8 col-md-6 '
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with players_with_aces as (',
'      select c.id course_id, tc.course_no, r.player_id',
'        from wmg_rounds_unpivot_mv r',
'           , wmg_tournament_courses tc',
'           , wmg_courses c',
'       where tc.course_id = r.course_id',
'         and r.course_id = c.id',
'         and r.week = :P100_WEEK',
'         and tc.tournament_session_id = :P100_TOURNAMENT_SESSION_ID',
'         and r.score = 1',
')',
'select 100 + course_no display_seq, ''Best score '' || course_code result, listagg(player_name, '', '') who, total',
'from (',
'      select r.*, rank() over (partition by course_no order by r.total) rn',
'      from (',
'      select tc.course_no, r.course_code, r.player_id, r.player_name, sum(r.under_par) total',
'        from wmg_rounds_v r',
'           , wmg_tournament_courses tc',
'       where tc.tournament_session_id = r.tournament_session_id',
'         and tc.course_id = r.course_id',
'         and tc.tournament_session_id = :P100_TOURNAMENT_SESSION_ID',
'       group by tc.course_no, r.course_code, r.player_id, r.player_name',
'      ) r',
'      order by course_no, course_code, rn, r.player_name',
')',
'where rn = 1',
'group by  course_no, course_code, total',
'union all',
'select 200 display_seq, result, listagg(who, '', '') who, total',
'from (',
'    select result, who, total, rank() over (order by total desc) rn',
'    from (',
'    select ''<i class="em em-gem" aria-role="presentation" aria-label="DIAMOND"></i> ''',
'        || ''Player(s) with most Aces'' result',
'         , r.player_name who',
'         , sum(decode(s1, 1, 1, 0)',
'             + decode(s2, 1, 1, 0)',
'             + decode(s3, 1, 1, 0)',
'             + decode(s4, 1, 1, 0)',
'             + decode(s5, 1, 1, 0)',
'             + decode(s6, 1, 1, 0)',
'             + decode(s7, 1, 1, 0)',
'             + decode(s8, 1, 1, 0)',
'             + decode(s9, 1, 1, 0)',
'             + decode(s10, 1, 1, 0)',
'             + decode(s11, 1, 1, 0)',
'             + decode(s12, 1, 1, 0)',
'             + decode(s13, 1, 1, 0)',
'             + decode(s14, 1, 1, 0)',
'             + decode(s15, 1, 1, 0)',
'             + decode(s16, 1, 1, 0)',
'             + decode(s17, 1, 1, 0)',
'             + decode(s18, 1, 1, 0)',
'          ) total',
'      from wmg_rounds_v r',
'     where r.week = :P100_WEEK',
'    group by r.player_name',
'    ) aces',
'    order by aces.who',
')',
'where rn = 1',
'group by result, total',
'union all',
'select 300 display_seq, ''<i class="em em-coconut" title="Coconut"></i> Coconuts'' result, '' - Listed in Results -'' who,  count(*) total',
'from (',
'    select u.week',
'      from wmg_rounds_unpivot_mv u',
'         , wmg_tournament_sessions ts',
'         , wmg_tournament_players tp',
'     where ts.week = u.week',
'       and ts.id = tp.tournament_session_id',
'       and tp.player_id = u.player_id',
'       and tp.issue_code is null  -- only players with no issues are eligible',
'       and u.week = :P100_WEEK',
'     having sum(case when par <= 0 then 1 else 0 end) = 36',
'     group by u.week, u.player_id',
')',
'union all',
'select 400 display_seq, ''Players w/zero Aces on Course 1'' result, ''- Undisclosed -'' who, count(*) total',
'from ( ',
'   select player_id',
'    from wmg_rounds_v r',
'       , wmg_tournament_courses tc',
'     where tc.tournament_session_id = r.tournament_session_id',
'       and tc.tournament_session_id = :P100_TOURNAMENT_SESSION_ID',
'       and tc.course_no = 1',
'  minus  -- all players, minus players with aces',
'   select player_id',
'    from players_with_aces',
'   where course_no = 1',
')',
'union all',
'select 410 display_seq, ''Players w/zero Aces on Course 2'' result, ''- Undisclosed -'' who, count(*) total',
'from ( ',
'   select player_id',
'    from wmg_rounds_v r',
'       , wmg_tournament_courses tc',
'     where tc.tournament_session_id = r.tournament_session_id',
'       and tc.tournament_session_id = :P100_TOURNAMENT_SESSION_ID',
'       and tc.course_no = 2',
'  minus  -- all players, minus players with aces',
'   select player_id',
'    from players_with_aces',
'   where course_no =2',
')',
'order by display_seq',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P100_WEEK,P100_TOURNAMENT_SESSION_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
