,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_action=>'PLUGIN_UC_NESTED_REPORTS'
,p_affected_elements_type=>'JQUERY_SELECTOR'
,p_affected_elements=>'#statsRegion'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with week_courses as (',
'select c.course_id, :P100_WEEK week from wmg_courses_v c, wmg_tournament_courses tc where c.course_id = tc.course_id and tc.tournament_session_id = :P100_TOURNAMENT_SESSION_ID',
'     and course_no = #COURSE_NO#',
')',
'select r.player_name "Player"',
' , case :P100_H ',
'   when ''H1'' then r.s1',
'   when ''H2'' then r.s2',
'   when ''H3'' then r.s3',
'   when ''H4'' then r.s4',
'   when ''H5'' then r.s5',
'   when ''H6'' then r.s6',
'   when ''H7'' then r.s7',
'   when ''H8'' then r.s8',
'   when ''H9'' then r.s9',
'   when ''H10'' then r.s10',
'   when ''H11'' then r.s11',
'   when ''H12'' then r.s12',
'   when ''H13'' then r.s13',
'   when ''H14'' then r.s14',
'   when ''H15'' then r.s15',
'   when ''H16'' then r.s16',
'   when ''H17'' then r.s17',
'   when ''H18'' then r.s18',
' else null end "Score"',
'from wmg_rounds_v r, week_courses w',
'where r.week = w.week',
' and r.course_id = w.course_id',
' and (',
' (#DATA_FILTER# = 99 -- Aces',
'    and (',
'       (:P100_H = ''H1'' and r.s1 = 1)',
'    or (:P100_H = ''H2'' and r.s2 = 1)',
'    or (:P100_H = ''H3'' and r.s3 = 1)',
'    or (:P100_H = ''H4'' and r.s4 = 1)',
'    or (:P100_H = ''H5'' and r.s5 = 1)',
'    or (:P100_H = ''H6'' and r.s6 = 1)',
'    or (:P100_H = ''H7'' and r.s7 = 1)',
'    or (:P100_H = ''H8'' and r.s8 = 1)',
'    or (:P100_H = ''H9'' and r.s9 = 1)',
'    or (:P100_H = ''H10'' and r.s10 = 1)',
'    or (:P100_H = ''H11'' and r.s11 = 1)',
'    or (:P100_H = ''H12'' and r.s12 = 1)',
'    or (:P100_H = ''H13'' and r.s13 = 1)',
'    or (:P100_H = ''H14'' and r.s14 = 1)',
'    or (:P100_H = ''H15'' and r.s15 = 1)',
'    or (:P100_H = ''H16'' and r.s16 = 1)',
'    or (:P100_H = ''H17'' and r.s17 = 1)',
'    or (:P100_H = ''H18'' and r.s18 = 1)',
