'  select id course_id, course_mode, :P100_WEEK week',
'    from wmg_courses',
'   where id in (',
'      select distinct course_id',
'        from wmg_rounds ',
'       where week = :P100_WEEK ',
'    )',
'   and course_mode = ''#COURSE_MODE#''',
')',
'select r.account "Player"',
'     , case :P100_H ',
'     when ''H1'' then r.s1',
'     when ''H2'' then r.s2',
'     when ''H3'' then r.s3',
'     when ''H4'' then r.s4',
'     when ''H5'' then r.s5',
'     when ''H6'' then r.s6',
'     when ''H7'' then r.s7',
'     when ''H8'' then r.s8',
'     when ''H9'' then r.s9',
'     when ''H10'' then r.s10',
