'     when ''H13'' then r.s13',
'     when ''H14'' then r.s14',
'     when ''H15'' then r.s15',
'     when ''H16'' then r.s16',
'     when ''H17'' then r.s17',
'     when ''H18'' then r.s18',
'   else null end "Score"',
'  from wmg_rounds_v r, week_courses w',
