' into :P100_TOURNAMENT_SESSION_ID',
'    , :P100_EASY_ID',
'    , :P100_HARD_ID',
'from wmg_tournament_sessions_v s',
'where s.week = :P100_WEEK;',
'',
'if :P100_EASY_ID is null then',
'  :P100_EASY := '''';',
'  :P100_EASY_CODE := ''TBD'';',
'else',
'    select name',
'         , code',
'      into :P100_EASY',
'         , :P100_EASY_CODE',
'        from wmg_courses_v',
'       where course_id = :P100_EASY_ID;',
'end if;',
'',
'if :P100_HARD_ID is null then',
'  :P100_HARD:= '''';',
'  :P100_HARD_CODE := ''TBD'';',
'else',
'  select name',
'       , code',
'    into :P100_HARD',
'       , :P100_HARD_CODE',
'    from wmg_courses_v',
'   where course_id = :P100_HARD_ID;',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>20760559352070173440
);
