wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(98831107075198136964)
,p_name=>'Player Round Details'
,p_region_name=>'roundDetails'
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--hideHeader:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select player_name',
'     , r.course_id',
'     , course_mode',
'     , course_code',
'     , course_name',
'     , s1',
'     , case when s1 = 1 then ''HIO'' when s1>h1 then ''OVER'' end s1_status',
'     , s2',
'     , case when s2 = 1 then ''HIO'' when s2>h2 then ''OVER'' end s2_status',
'     , s3',
'     , case when s3 = 1 then ''HIO'' when s3>h3 then ''OVER'' end s3_status',
'     , s4',
'     , case when s4 = 1 then ''HIO'' when s4>h4 then ''OVER'' end s4_status',
'     , s5',
'     , case when s5 = 1 then ''HIO'' when s5>h5 then ''OVER'' end s5_status',
'     , s6',
'     , case when s6 = 1 then ''HIO'' when s6>h6 then ''OVER'' end s6_status',
'     , s7',
'     , case when s7 = 1 then ''HIO'' when s7>h7 then ''OVER'' end s7_status',
'     , s8',
'     , case when s8 = 1 then ''HIO'' when s8>h8 then ''OVER'' end s8_status',
'     , s9',
'     , case when s9 = 1 then ''HIO'' when s9>h9 then ''OVER'' end s9_status',
'     , s10',
'     , case when s10 = 1 then ''HIO'' when s10>h10 then ''OVER'' end s10_status',
'     , s11',
'     , case when s11 = 1 then ''HIO'' when s11>h11 then ''OVER'' end s11_status',
'     , s12',
'     , case when s12 = 1 then ''HIO'' when s12>h12 then ''OVER'' end s12_status',
'     , s13',
'     , case when s13 = 1 then ''HIO'' when s13>h13 then ''OVER'' end s13_status',
'     , s14',
'     , case when s14 = 1 then ''HIO'' when s14>h14 then ''OVER'' end s14_status',
'     , s15',
'     , case when s15 = 1 then ''HIO'' when s15>h15 then ''OVER'' end s15_status',
'     , s16',
'     , case when s16 = 1 then ''HIO'' when s16>h16 then ''OVER'' end s16_status',
'     , s17',
'     , case when s17 = 1 then ''HIO'' when s17>h17 then ''OVER'' end s17_status',
'     , s18',
'     , case when s18 = 1 then ''HIO'' when s18>h18 then ''OVER'' end s18_status',
'     , round_strokes',
'     , under_par',
'  from wmg_rounds_v r',
'     , wmg_tournament_courses tc',
'  where r.tournament_session_id = tc.tournament_session_id',
'    and r.course_id = tc.course_id',
'    and r.week = :P110_WEEK',
'    and r.player_id = :P110_PLAYER_ID',
'order by tc.course_no'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P110_WEEK,P110_PLAYER_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>50
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No scores for the player.'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>500
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_prn_format=>'PDF'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
