,p_name=>'Badges & Achivements'
,p_region_name=>'playerBadges'
,p_parent_plug_id=>wwv_flow_imp.id(115116300288178746)
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--noBorder:js-headingLevel-3:t-Region--scrollBody:t-Form--slimPadding'
,p_component_template_options=>'#DEFAULT#:t-Report--staticRowColors:t-Report--rowHighlightOff:t-Report--noBorders'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with tournament_sessions as (',
'    select id tournament_session_id',
'      from wmg_tournament_sessions',
'     where tournament_id = :P120_TOURNAMENT_ID',
')',
', player_uni as (',
' select player_id, sum(n) n  -- make sure we always get a row',
' from (',
'     select to_number(:P120_PLAYER_ID) player_id, 0 n from dual -- add a zero count row',
'     union all ',
'      select u.player_id, count(*) n ',
'        from wmg_player_unicorns u',
'       where u.player_id (+) = :P120_PLAYER_ID',
'         and (:P120_TOURNAMENT_ID is null ',
'          or u.score_tournament_session_id in (',
'                select tournament_session_id',
'                from tournament_sessions',
'          )',
'        )',
'        group by u.player_id',
'   )',
'  group by player_id',
')',
', player as (',
' select code',
'      ,  (select listagg(icon_class, '' '') from dual connect by level <= n) all_badges',
'from (',
' select b.code, replace(b.icon_class, ''em em'', ''em'') icon_class, sum(p.badge_count)  n',
'--      , listagg(replace(b.icon_class, ''em em'', ''em''), '' '') within group ( order by b.display_seq) all_badges',
'      -- , replace(b.icon_class, ''em em'', ''em'') all_badges',
'  from wmg_player_badges p',
'     , wmg_badge_types b',
'  where b.code = p.badge_type_code ',
'    and (:P120_TOURNAMENT_ID is null ',
'      or p.tournament_session_id in (',
'            select tournament_session_id',
'            from tournament_sessions',
'      )',
'    )',
'    and p.player_id (+) = :P120_PLAYER_ID',
'  group by b.code, b.icon_class',
')',
')',
'select b.name',
'     , b.icon_class',
'     , b.description',
'     , case b.code',
'             when ''UNICORN'' then',
'            decode(u.n, 0, '''', (select listagg(replace(b.icon_class, ''em em'', ''em''), '' '') from dual connect by level <= u.n) )',
'        else',
'           player.all_badges',
'        end all_badges',
'  from wmg_badge_types b',
'     , player',
'     , player_uni u',
' where b.active_ind = ''Y''',
'   and b.code = player.code (+)',
'--   and u.player_id (+) = :P120_PLAYER_ID',
'order by b.display_seq',
''))
,p_footer=>'"BADGES_BY_STEVEN"'
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P120_PLAYER_ID,P120_TOURNAMENT_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
