wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(108375020770068260631)
,p_name=>'Weekly Results'
,p_region_name=>'weekResults'
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>9
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:js-showMaximizeButton:t-Region--scrollBody:margin-left-none:margin-right-none'
,p_component_template_options=>'#DEFAULT#:t-Report--staticRowColors:t-Report--rowHighlightOff:t-Report--verticalBorders'
,p_new_grid_row=>false
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with badges as (',
' select p.tournament_session_id, p.player_id',
'        -- need to expand by the badge_count, because people can habe multiple-badges',
'      , listagg( (select listagg(replace(b.icon_class, ''em em'', ''em''), '' '') from dual connect by level <= p.badge_count) , '' '')  within group ( order by b.display_seq) other_badges',
'      , json_objectagg(key p.badge_type_code value case when p.badge_count>=1 then ''true'' else ''false'' end) badge_json',
'  from wmg_player_badges p',
'     , wmg_badge_types b',
'  where p.badge_type_code = b.code',
'    and b.selectable_ind = ''Y''',
'  group by p.tournament_session_id, p.player_id',
')',
', unicorns as (',
' select u.score_tournament_session_id tournament_session_id, u.player_id',
'        -- need to expand by the badge_count, because people can habe multiple-badges',
'      , listagg( replace(b.icon_class, ''em em'', ''em''), '' '')  within group ( order by b.display_seq) unicorn_badges',
'  from wmg_player_unicorns u',
'     , wmg_badge_types b',
'  where b.code = ''UNICORN''',
'  group by u.score_tournament_session_id, u.player_id',
')',
'select sp.week',
'     , sp.pos',
'     , sp.player_id',
'     , wmg_discord.avatar_link(pp.discord_id, pp.discord_avatar) avatar',
'     , pp.country_code',
'     , pp.country',
'     , pp.player_name',
'     , sp.easy_course_id, sp.hard_course_id',
'     , ec.code easy_course_code',
'     , ec.name easy_course',
'     , hc.code hard_course_code',
'     , hc.name hard_course',
'     , sp.easy',
'     , sp.hard',
'     , sp.easy_round_id, sp.hard_round_id',
'     , sp.total_score',
'     , p.points',
'     , case when sp.pos <= 10 then ''top'' else ''p'' || to_char(p.points) end',
'     || case when p.points <= 0 then '' missing tooltip'' end',
'     || case when sp.pos <= 3 then '' podium podium'' || sp.pos  end point_class',
'     , case when p.points <= 0 then ''Disqualified, Failed to complete round, or failed to submit scores before deadline'' end points_title',
'     , decode(p.player_id, :G_PLAYER_ID, ''mark'', '''') selected_player',
'     , case when sp.pos = 1 then ''<i class="em em-trophy" aria-role="presentation" aria-label="TROPHY"></i>'' else '''' end trophy',
'     , pp.rank_code',
'     , pp.rank_name',
'     , pp.rank_list_class',
'     , case when sp.completed_ind = ''N'' then',
'         case sp.pos ',
'         when 1 then ''em-first_place_medal ''',
'         when 2 then ''em-second_place_medal ''',
'         when 3 then ''em-third_place_medal ''',
'         end',
'       end',
'    || badges.other_badges || '' '' || unicorns.unicorn_badges badges',
'     , i.icon issue_icon',
'     , i.description issue_description',
'     , p.issue_code',
'from wmg_tournament_session_points_v sp',
'     join wmg_players_v pp on pp.id = sp.player_id',
'     join wmg_courses ec on ec.id = sp.easy_course_id',
'     join wmg_courses hc on hc.id = sp.hard_course_id',
'left join wmg_tournament_players p on sp.tournament_session_id = p.tournament_session_id',
'                                  and sp.player_id = p.player_id',
'left join badges on sp.tournament_session_id = badges.tournament_session_id',
'                and sp.player_id = badges.player_id ',
'left join unicorns on sp.tournament_session_id = unicorns.tournament_session_id',
'                and sp.player_id = unicorns.player_id ',
'left join wmg_issues i on  p.issue_code = i.code',
'order by sp.week, p.points desc, sp.pos, nls_upper(sp.player_name)'))
,p_optimizer_hint=>'WITH_PLSQL'
,p_header=>'<div id="currentFacets"></div>'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>250
