begin
wwv_flow_imp_page.create_page(
 p_id=>200
,p_name=>'Course Analysis'
,p_alias=>'COURSE-ANALYSIS'
,p_step_title=>'Course Analysis'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var refreshingThings = 0;',
'var selectedRank = "", selectedRankClass = "";',
'',
'function refreshAllThings() {',
'    apex.submit({showWait:true});',
'    return; // do not do live reloading any more on change of course',
'    // at this point we want to save on concurrent sessions hitting the DB. We are very limited on ATP, so a submit reduces ',
'    // the count from 7 to 5 which at this point is significant enough',
'',
'	if (!refreshingThings) {',
'		refreshingThings = 1;',
'		[',
'		''topPlayersRegion'', ',
'		''courseStatsChart'',',
'		''strokeHistogram'',',
'        ''courseDetails'',',
'		''buttonPreviewJS'',',
'		''unicornAces'',',
'		''futureUnicornAces'',',
'		''allCoursesChart'',',
'	    ].forEach((region) => {',
'          // console.log(region);',
'          try {',
'              apex.region(region).refresh();',
'          }',
'          catch (e) {};',
'        });',
'		refreshingThings = 0;',
'	}',
'}',
'',
'function refreshHoleThings() {',
'	if (!refreshingThings) {',
'		refreshingThings = 1;',
'		[',
'		''strokeHistogram'',',
'		''courseStatsChart'',',
'        ''topPlayersRegion'',',
'		''buttonPreviewJS'',',
'	    ].forEach((region) => apex.region(region).refresh());',
'		refreshingThings = 0;',
'	}',
'}',
'',
'function drill(pScore) {',
'    $s("P200_S", pScore);',
'    apex.region("playersDrilldown").refresh();',
'    openModal("playersDrilldown");',
'}',
'',
'function switchCourse(pCourse) {',
'    $s("P200_TOURNAMENT_SESSION_ID", "", "", true);',
'    $s("P200_COURSE_ID", pCourse, "- Loading -", true);',
'    apex.submit("REFRESH");',
'}'))
,p_css_file_urls=>'//emoji-css.afeld.me/emoji.css'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#P200_H {',
'    min-width: 4rem;',
'}',
'',
'#P200_GOALS_IND_CONTAINER {',
'--ut-field-padding-y: 0;',
'--a-field-input-padding-y: 0px;',
'}',
'',
'.topScores .t-Report-report tr:nth-child(1) {',
'    background-color: var(--u-color-4);',
'    color: var(--u-color-4-contrast);',
'}',
'.topScores .t-Report-report tr:nth-child(2) {',
'    background-color: var(--u-color-5);',
'    color: var(--u-color-5-contrast);',
'}',
'.topScores .t-Report-report tr:nth-child(3) {',
'    background-color: var(--u-color-3);',
'    color: var(--u-color-3-contrast);',
'}',
'',
'/* unicorn drilldown */',
'.uc_plugin_row table.t-Report-report {',
'    float: right;',
'}',
''))
,p_page_template_options=>'#DEFAULT#'
,p_page_is_public_y_n=>'Y'
,p_page_component_map=>'25'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(31444386482255643)
,p_name=>'Players'
,p_region_name=>'playersDrilldown'
,p_template=>wwv_flow_imp.id(47017538176820127362)
,p_display_sequence=>130
,p_include_in_reg_disp_sel_yn=>'Y'
