,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select p.player_name, u.score, count(*) times, listagg(u.week, '', '') weeks',
'from  wmg_rounds_unpivot_mv u',
'    , wmg_players_v p',
'    , wmg_rounds r',
'where u.player_id = p.id',
'  and u.course_id = :P200_COURSE_ID',
'  and u.h = :P200_H',
'  and u.score = :P200_S',
'  and u.player_id > 0',
'  and u.week = r.week',
'  and u.course_id = r.course_id',
'  and u.player_id = r.players_id',
'  and (wmg_rank_history.get_round_effective_rank(r.id) = :P200_RANK_SELECTOR or :P200_RANK_SELECTOR is null)',
'group by p.player_name, u.score',
'order by 3 desc, p.player_name'))
