 p_id=>wwv_flow_imp.id(31590294485997840)
,p_plug_name=>'Top 15 Easiest Holes'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(47017557400631127370)
,p_plug_display_sequence=>110
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_grid_column_span=>6
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with std_scale as (',
'   select max(std_dev) max_std_dev',
'     from wmg_course_stats_v',
')',
'select s.course_id, s.course_code, s.h',
'     ,  case :P200_FORMULA',
'         when ''SCORE'' then',
'           s.score_avg',
'         when ''STDDEV'' then',
'            case ',
'              when s.std_dev = 0 then 0',
'              else round(s.std_dev / std_scale.max_std_dev * 10,1)',
'            end',
'        when ''HYBRID'' then',
'          sqrt( s.score_avg * (',
'              case ',
'              when s.std_dev = 0 then 0',
'              else round(s.std_dev / std_scale.max_std_dev * 10,1)',
'            end',
'          ))',
'        end  difficulty',
'     , case when course_id = :P200_COURSE_ID and h = :P200_H then ''gold'' else ''#4c825c'' end color',
'     , course_code || '' #'' || h label',
'from  wmg_course_stats_v s',
'   , std_scale',
'order by difficulty',
'fetch first 15 rows only'))
,p_plug_source_type=>'NATIVE_JET_CHART'
,p_ajax_items_to_submit=>'P200_COURSE_ID, P200_FORMULA, P200_H'
