,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlightOff:t-Report--hideNoPagination'
,p_grid_column_span=>9
,p_grid_column_css_classes=>'col-sm-12 col-md-12'
,p_display_column=>2
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
' with course_play_count as (',
'        select c.course_id',
'             , count(*) play_count',
'             , sum(decode(s.completed_ind, ''Y'', 1, 0)) real_play_count',
'        from wmg_tournament_courses c',
'           , wmg_tournament_sessions s',
'       where s.id = c.tournament_session_id',
'         and s.session_date <= (select nvl(max(ts.session_date), sysdate) from wmg_tournament_sessions ts where ts.id = :G_CURRENT_SESSION_ID)',
'      and (',
'            (:P200_ALL_COURSES_IND = ''Y'' or :P200_ALL_MINE_IND = ''Y'') ',
'            or (c.course_id = :P200_COURSE_ID)',
'          )',
'        group by c.course_id',
')',
', courses_played as (',
'    select c.course_id, c.name course_name',
'         , cc.play_count',
'         , cc.real_play_count',
'    from wmg_courses_v  c',
'       , course_play_count cc',
'    where c.course_id = cc.course_id',
')',
'select cp.course_name, to_number(null) course_id',
'     , case when cp.play_count > cp.real_play_count then ''Y'' else ''N'' end scheduled_ind',
'     , cp.play_count',
'     , to_number(null) h',
'     , to_number(null) hole',
'     , ''Course is not eligible yet'' ace_by',
'     , '''' on_week, to_date(null) score_session_date',
'     , '''' award_week, to_date(null) award_session_date',
'     , to_number(null) attempt_count',
'     , to_number(null) repeat_count',
'     , to_number(1) course_release_order, null course_mode',
'from  courses_played cp',
'where cp.play_count < 5',
'  and nvl(:P200_ALL_COURSES_IND,''N'') = ''N''',
'  and nvl(:P200_ALL_MINE_IND,''N'') = ''N''',
'  and :P200_UNICORN_PLAYERS_ID is null',
'union all',
'select u.course_name, u.course_id',
'     , case when cp.play_count > cp.real_play_count then ''Y'' else ''N'' end scheduled_ind',
'     , cp.play_count',
'     , u.h',
'     , u.h hole',
'     , u.player_name ace_by',
'     , u.score_week, u.score_session_date',
'     , u.award_week, u.award_session_date',
'     , u.attempt_count',
'     , u.repeat_count',
'     , u.course_release_order',
'     , u.course_mode',
'from wmg_player_unicorns_v u',
'join courses_played cp on cp.course_id = u.course_id',
'where ( ',
'          (:P200_ALL_COURSES_IND = ''Y'' or :P200_ALL_MINE_IND = ''Y'') ',
'       or u.course_id = :P200_COURSE_ID',
'      )',
'  and (',
'        (nvl(:P200_ALL_MINE_IND,''N'') = ''Y'' and u.player_id = :G_PLAYER_ID)',
'      or ',
'         ( nvl(:P200_ALL_COURSES_IND, ''N'') = ''N'' and nvl(:P200_ALL_MINE_IND,''N'') = ''N'') ',
'      or',
'      ( ',
'          (:P200_ALL_COURSES_IND = ''Y'' and nvl(:P200_ALL_MINE_IND,''N'') = ''N'') and u.player_id = nvl(:P200_UNICORN_PLAYERS_ID, u.player_id)',
'      )',
'  )',
'order by course_release_order, course_mode, h, ace_by'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P200_COURSE_ID,P200_ALL_COURSES_IND,P200_ALL_MINE_IND,P200_UNICORN_PLAYERS_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>25
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_break_cols=>'1:2'
,p_query_no_data_found=>'No Unicorn Aces'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_break_before_row=>'Course Played:'
,p_break_type_flag=>'DEFAULT_BREAK_FORMATTING'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
