wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(66836324083733423)
,p_name=>'Available or Potential Unicorns'
,p_region_name=>'futureUnicornAces'
,p_parent_plug_id=>wwv_flow_imp.id(58509562979788846)
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noBorder:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight:t-Report--hideNoPagination'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with course_play_count as (',
'    select c.course_id',
'         , count(*) play_count',
'         , sum(decode(s.completed_ind, ''Y'', 1, 0)) real_play_count',
'         , max(s.week) week, max(s.session_date) session_date',
'    from wmg_tournament_courses c',
'       , wmg_tournament_sessions s',
'    where s.id = c.tournament_session_id',
'      and s.session_date <= (select nvl(max(ts.session_date), sysdate) from wmg_tournament_sessions ts where ts.id = :G_CURRENT_SESSION_ID)',
'      and c.course_id = :P200_COURSE_ID',
'    group by c.course_id',
')',
', courses_played as (',
'  select c.course_id, c.name course_name, cc.play_count, cc.real_play_count, cc.week, cc.session_date',
'  from wmg_courses_v  c',
'     , course_play_count cc',
'  where c.course_id = cc.course_id',
'    and cc.play_count >= 1',
')',
', missing_ace as (',
'    select level h',
'    from dual',
'    connect by level <= 18',
'    minus',
'    select distinct h',
'    from wmg_rounds_unpivot_mv',
'    where course_id = :P200_COURSE_ID',
'    and score = 1',
')',
'select cp.course_name',
'     , cp.course_id',
'     , cp.play_count',
'     , cp.real_play_count',
'     , m.h',
'     , '''' week',
'     , '' - never aced -'' ace_by',
'from missing_ace m',
'   , courses_played cp',
'union all',
'select uni.course_name',
'       , uni.course_id',
'       , uni.play_count',
'       , uni.real_play_count',
'       , uni.h',
'       , uni.week',
'        -- for debuging',
'       , (select listagg(p.player_name, '','') player_name',
'        from wmg_rounds_unpivot_mv u',
'           , wmg_players_v p',
'       where u.player_id = p.id',
'         and u.course_id = uni.course_id',
'         and u.h = uni.h',
'         and u.week <= uni.week',
'         and u.score = 1) ace_by',
'  from (',
'      select u.course_id, cp.course_name, cp.play_count, cp.real_play_count, u.h',
'           , max(u.week) week',
'        from wmg_rounds_unpivot_mv u',
'           , courses_played cp',
'        where u.score = 1',
'          and u.course_id = cp.course_id',
'          and cp.play_count >= 5',
'          and u.week in (select ts.week from wmg_tournament_sessions ts where ts.session_date <= cp.session_date)',
'          and (u.course_id, u.h) not in (select course_id, h from wmg_player_unicorns) -- eliminate previous unicorns',
'        group by u.course_id, cp.course_name, cp.play_count, cp.real_play_count, u.h',
'       having count(*) = 1',
'  ) uni',
'  order by course_name, ace_by desc, h',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P200_COURSE_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_break_cols=>'1'
,p_query_no_data_found=>'No new potential Unicorns yet'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_break_type_flag=>'DEFAULT_BREAK_FORMATTING'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
