wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(38586266144491836)
,p_name=>'Top Scores'
,p_region_name=>'topPlayersRegion'
,p_parent_plug_id=>wwv_flow_imp.id(61525046799634507)
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:i-h480:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with best_round as (',
'  select course_id, rank_code, sum(score) best_strokes',
'  from (',
'    select course_id, h, score, rank_code, row_number()  over (partition by course_id, rank_code, h order by people desc) rn',
'    from (',
'        select course_id, h, score, rank_code, count(*) people',
'        from (',
'            select u.course_id, u.h, wmg_rank_history.get_round_effective_rank(r.id) rank_code, u.score',
'              from  wmg_rounds_unpivot_mv u',
'                  , wmg_players_v p',
'                  -- , wmg_ranks ra',
'                  , wmg_rounds r',
'             where u.player_id = p.id',
'               and u.course_id = :P200_COURSE_ID',
'               and u.player_id != 0  -- remove the curated system score',
'               -- and p.rank_code = ra.code',
'               -- and ra.active_ind = ''Y''',
'               and u.player_id = r.players_id',
'               and u.week = r.week',
'               and u.course_id = r.course_id',
'         )',
'         group by course_id, h, rank_code, score',
'         order by course_id, h',
'    )',
'  )',
' where rn = 1',
' group by course_id, rank_code',
')',
'select week, player_name, under_par',
'from (',
'    select ''- Leaderboard - '' week, '''' player_name, min(l.score) under_par',
'    from wmg_leaderboards l',
'    where l.course_id = :P200_COURSE_ID',
'    union all',
'    select ''- Realistic - '' week, r.name player_name, b.best_strokes - c.course_par under_par',
'    from wmg_courses_v c',
'       , best_round b',
'       , wmg_ranks r',
'    where b.course_id = c.course_id',
'      and b.rank_code = r.code',
'      and c.course_id = :P200_COURSE_ID',
'      and (r.code = :P200_RANK_SELECTOR or :P200_RANK_SELECTOR is null)',
'    union all',
'    select ''- Utopian -'' week, '''' player_name, best_under under_par',
'    from wmg_courses_v',
'    where course_id = :P200_COURSE_ID',
'      and best_under is not null',
'    union all',
'    select max(week) week, player_name, under_par',
'    from wmg_rounds_v',
'    where course_id = :P200_COURSE_ID',
'      and (player_name, under_par) in (',
'        select player_name, min(under_par)',
'        from wmg_rounds_v',
'        where course_id = :P200_COURSE_ID',
'        group by player_name',
'        order by 2 asc',
'        fetch first 10 rows only',
'     )',
'     and :P200_GOALS_IND = ''N''',
'     group by player_name, under_par',
' )',
' order by ',
' -- decode(player_name, null, 1,2),',
' under_par asc, week'))
,p_footer=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="legend">',
unistr('\2022 The <b>Utopian</b> score is a theoretical score made of the best score on each hole from all players from all the times the course was played in the tournament<br>'),
unistr('\2022 The <b>Realistic</b> score is a good high score made of the most common score people obtain on a hole<br>'),
unistr('\2022 The <b>Leaderboard</b> score is the all-time high on The Leaderboards.<br>'),
'</div>'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P200_COURSE_ID,P200_GOALS_IND,P200_RANK_SELECTOR'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
