wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(31184791957431341)
,p_chart_id=>wwv_flow_imp.id(31184631199431340)
,p_static_id=>'stddev'
,p_seq=>10
,p_name=>'Std Dev Formula'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with std_scale as (',
'   select max(std_dev) max_std_dev',
'     from wmg_course_stats_v',
')',
', missing_ace as (',
'    select level h',
'    from dual',
'    connect by level <= 18',
'    minus',
'    select distinct h',
'      from wmg_rounds_unpivot_mv u',
'      , wmg_players p',
'  where u.player_id = p.id',
'    and u.player_id != 0  -- remove the curated system score',
'    and u.course_id = :P200_COURSE_ID',
'    and (p.rank_code = :P200_RANK_SELECTOR or :P200_RANK_SELECTOR is null)',
'    and u.score = 1',
')',
'select s.course_id, s.course_code, s.h',
'     , case :P200_FORMULA',
'         when ''SCORE'' then',
'           s.score_avg',
'         when ''STDDEV'' then',
'            case ',
'              when s.std_dev = 0 then 0',
'              else round(s.std_dev / std_scale.max_std_dev * 10,1)',
'            end',
'        when ''HYBRID'' then',
'          sqrt( s.score_avg * (',
'              case ',
'              when s.std_dev = 0 then 0',
'              else round(s.std_dev / std_scale.max_std_dev * 10,1)',
'            end',
'          ))',
'        end value',
'     , case when s.h = :P200_H then',
'         case when ma.h = s.h then ',
'           c.selected_highlight',
'         else',
'           c.selected',
'         end',
'       else',
'         case when ma.h = s.h then ',
'          c.regular_highlight',
'         else',
'          c.regular',
'         end',
'       end color',
'from  wmg_course_stats_v s',
'    , std_scale',
'    , missing_ace ma',
'    , wmg_bar_chart_colors c',
'where s.course_id = :P200_COURSE_ID',
'  and s.h = ma.h (+)',
'order by s.h'))
,p_max_row_count=>20
,p_ajax_items_to_submit=>'P200_COURSE_ID.P200_H,P200_FORMULA,P200_RANK_SELECTOR'
,p_items_value_column_name=>'VALUE'
,p_items_label_column_name=>'H'
,p_color=>'&COLOR.'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>false
,p_link_target=>'javascript:$s("P200_H", #H#)'
,p_link_target_type=>'REDIRECT_URL'
);
