wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(31442347481255623)
,p_chart_id=>wwv_flow_imp.id(31442270998255622)
,p_seq=>10
,p_name=>'Strokes'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with strokes as (',
'    select level stroke',
'     from dual ',
'   connect by level <= 10',
')',
', round as (',
'    select u.score, count(distinct u.player_id) people, count(*) n, sum(count(*)) over () all_scores',
'      from wmg_rounds_unpivot_mv u',
'         , wmg_players p',
'         , wmg_rounds r',
'    where u.player_id = p.id',
'      and u.player_id != 0  -- remove the curated system score',
'      and u.course_id = :P200_COURSE_ID',
'      and u.player_id = r.players_id',
'      and u.week = r.week',
'      and u.course_id = r.course_id',
'      and (wmg_rank_history.get_round_effective_rank(r.id) = :P200_RANK_SELECTOR or :P200_RANK_SELECTOR is null)',
'       and u.h = :P200_H',
'     group by u.score',
')',
'select stroke',
'     ,  n || '' time'' || decode(people, 1, '''', ''s'') ',
'    || '' in '' || stroke || '' stroke'' || decode(stroke, 1, '''', ''s'') ',
'    || '' by '' || people || '' player'' || decode(people, 1, '''', ''s'')',
'    || ''<br>'' ',
'    || ''('' || round(percent,1) || ''%)'' tooltip',
'    , percent ',
'from (',
'    select s.stroke, r.n, r.people, round(r.n * 100 / all_scores,2) percent',
'    from  round r',
'        , strokes s',
'   where s.stroke = r.score (+)',
')',
'order by stroke'))
,p_max_row_count=>200
,p_ajax_items_to_submit=>'P200_COURSE_ID,P200_H,P200_RANK_SELECTOR'
,p_items_value_column_name=>'PERCENT'
,p_items_label_column_name=>'STROKE'
,p_items_short_desc_column_name=>'TOOLTIP'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>true
,p_items_label_position=>'auto'
,p_link_target=>'javascript:drill(#STROKE#);'
,p_link_target_type=>'REDIRECT_URL'
);
