wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(71984367608133804)
,p_plug_name=>'Preview Hole in Button'
,p_region_name=>'buttonPreviewJS'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(47017498405884127346)
,p_plug_display_sequence=>150
,p_include_in_reg_disp_sel_yn=>'Y'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for p in (',
'select apex_page.get_url(p_page => 16',
'                       , p_items=>''P16_C,P16_H''',
'                       , p_values => p.course_id || '','' || :P200_H) url',
'     , 7 button_size',
'from wmg_course_previews_v p',
'   , wmg_courses_v c',
'where 1 = 1 ',
'  and p.course_id = c.course_id',
'  and c.course_id = :P200_COURSE_ID',
'  and p.hole = nvl(:P200_H,0)',
'union all',
'select :BUCKET || course_emoji || ''.webp'' url',
'     , 5 button_size',
'from wmg_courses',
'where id = :P200_COURSE_ID',
'  and :P200_H is null',
'  and course_emoji is not null',
')',
'loop',
'return ''<style>''',
'|| ''#PREVIEW_BTN {',
'    background-image: url('' || p.url || '');',
'    background-size: cover;',
'    width: '' || p.button_size || ''rem;',
'    height: '' || p.button_size || ''rem;',
'    position: absolute;',
'    right: 2rem;',
'    top: 4rem;',
'    z-index: 1;',
'}',
'#PREVIEW_BTN .t-Icon {display: none;}''',
'|| ''</style>'';',
'end loop;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P200_H,P200_COURSE_ID'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(71987855859133839)
,p_plug_name=>'Top 15 Most Difficult Holes'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(47017557400631127370)
,p_plug_display_sequence=>120
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_new_grid_row=>false
,p_plug_grid_column_span=>6
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with std_scale as (',
'   select max(std_dev) max_std_dev',
'     from wmg_course_stats_v',
')',
'select s.course_id, s.course_code, s.h',
'     ,  case :P200_FORMULA',
'         when ''SCORE'' then',
'           s.score_avg',
'         when ''STDDEV'' then',
'            case ',
'              when s.std_dev = 0 then 0',
'              else round(s.std_dev / std_scale.max_std_dev * 10,1)',
'            end',
'        when ''HYBRID'' then',
'          sqrt( s.score_avg * (',
'              case ',
'              when s.std_dev = 0 then 0',
'              else round(s.std_dev / std_scale.max_std_dev * 10,1)',
'            end',
'          ))',
'        end  difficulty',
'     , case when course_id = :P200_COURSE_ID and h = :P200_H then ''gold'' else ''#4c825c'' end color',
'     , s.course_code || '' #'' || s.h label',
'from  wmg_course_stats_v s',
'   , std_scale',
'order by difficulty desc',
'fetch first 15 rows only'))
,p_plug_source_type=>'NATIVE_JET_CHART'
,p_ajax_items_to_submit=>'P200_COURSE_ID, P200_FORMULA, P200_H'
);
