 p_id=>wwv_flow_imp.id(48859109589550829)
,p_name=>'Multiple Season Wins'
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--staticRowColors:t-Report--rowHighlightOff:t-Report--horizontalBorders:t-Report--hideNoPagination'
,p_new_grid_row=>false
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with all_points as (',
'        select ts.tournament_id ',
'             , p.player_id',
'             , sum(case when p.discarded_points_flag = ''Y'' then 0 else p.points end) season_total',
'        from wmg_tournaments t',
'           , wmg_tournament_sessions ts',
'           , wmg_tournament_players p',
'        where t.id = ts.tournament_id',
'          and ts.id = p.tournament_session_id',
'          and p.active_ind = ''Y''',
'          and t.active_ind = ''Y''',
'          and t.current_flag is null',
'       group by ts.tournament_id, p.player_id',
')',
', w_seasons_rank as (',
'    select rank() over (partition by p.tournament_id order by p.season_total desc nulls last) pos',
'         , p.*',
'    from all_points p',
')',
'select p.id player_id',
'     , p.player_name',
'     , p.avatar_image',
'     , count(*) n',
'  from w_seasons_rank sr',
'     , wmg_tournaments t',
'     , wmg_players_v p',
' where sr.tournament_id = t.id',
'   and p.id = sr.player_id',
'   and sr.pos = 1',
'group by p.id, p.player_name, p.avatar_image',
'having count(*)> 1',
'order by n desc',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
