,p_affected_region_id=>wwv_flow_imp.id(105939655749323238)
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  with week_aces as (',
'      select u.week',
'           , u.player_id',
'           , count(*) as aces',
'      from wmg_rounds_unpivot_mv u',
'      where u.player_id = #PLAYER_ID#',
'        and u.score = 1',
'        and u.player_id > 0',
'      group by u.week, u.player_id',
'      having count(*) = #ACES#',
'  ),',
'  course_aces as (',
'      select u.week',
'           , u.player_id',
'           , u.course_id',
'           , count(*) as course_aces',
'      from wmg_rounds_unpivot_mv u',
'      where u.player_id = #PLAYER_ID#',
'        and u.score = 1',
'        and u.player_id > 0',
'      group by u.week, u.player_id, u.course_id',
'  ),',
'  rounds as (',
'      select r.week',
'           , r.player_id',
'           , r.course_id',
'           , r.course_name',
'           , r.course_code',
'           , r.course_mode',
'           , r.under_par as score',
'      from wmg_rounds_v r',
'      where r.player_id = #PLAYER_ID#',
'  )',
'  select w.week as "Week"',
'       , max(case when r.course_mode = ''E'' then r.course_name end) as "Easy Course"',
'       , max(case when r.course_mode = ''H'' then r.course_name end) as "Hard Course"',
'       , max(case when r.course_mode = ''E'' then ca.course_aces end) as "Easy Aces"',
'       , max(case when r.course_mode = ''H'' then ca.course_aces end) as "Hard Aces"',
'       , w.aces as "Aces"',
'       , max(case when r.course_mode = ''E'' then r.score end) as "Easy Score"',
'       , max(case when r.course_mode = ''H'' then r.score end) as "Hard Score"',
'  from week_aces w',
'  join rounds r',
'    on r.week = w.week',
'   and r.player_id = w.player_id',
'  left join course_aces ca',
'    on ca.week = r.week',
'   and ca.player_id = r.player_id',
'   and ca.course_id = r.course_id',
'  group by w.week, w.aces',
'  order by w.week desc'))
,p_attribute_02=>'CR:AA:LI'
,p_attribute_03=>'DTDC'
,p_attribute_06=>'#EBEBEB'
,p_attribute_08=>'#c5c5c5'
,p_attribute_09=>'#e3e3e3'
,p_attribute_11=>'No data found'
,p_attribute_12=>'ATR'
);
end;
