 p_id=>313
,p_name=>'The Rest of the Story'
,p_alias=>'THE-REST-OF-THE-STORY'
,p_step_title=>'The Rest of the Story'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const pinchZoom = (imageElement) => {',
'  let imageElementScale = 1;',
'',
'  let start = {};',
'',
'  // Calculate distance between two fingers',
'  const distance = (event) => {',
'    return Math.hypot(event.touches[0].pageX - event.touches[1].pageX, event.touches[0].pageY - event.touches[1].pageY);',
'  };',
'',
'  imageElement.addEventListener(''touchstart'', (event) => {',
'    // console.log(''touchstart'', event);',
'    if (event.touches.length === 2) {',
'      event.preventDefault(); // Prevent page scroll',
'',
'      // Calculate where the fingers have started on the X and Y axis',
'      start.x = (event.touches[0].pageX + event.touches[1].pageX) / 2;',
'      start.y = (event.touches[0].pageY + event.touches[1].pageY) / 2;',
'      start.distance = distance(event);',
'    }',
'  });',
'',
'  imageElement.addEventListener(''touchmove'', (event) => {',
'    // console.log(''touchmove'', event);',
'    if (event.touches.length === 2) {',
'      event.preventDefault(); // Prevent page scroll',
'',
'      // Safari provides event.scale as two fingers move on the screen',
'      // For other browsers just calculate the scale manually',
'      let scale;',
'      if (event.scale) {',
'        scale = event.scale;',
'      } else {',
'        const deltaDistance = distance(event);',
'        scale = deltaDistance / start.distance;',
'      }',
'      imageElementScale = Math.min(Math.max(1, scale), 4);',
'',
'      // Calculate how much the fingers have moved on the X and Y axis',
'      const deltaX = (((event.touches[0].pageX + event.touches[1].pageX) / 2) - start.x) * 2; // x2 for accelarated movement',
'      const deltaY = (((event.touches[0].pageY + event.touches[1].pageY) / 2) - start.y) * 2; // x2 for accelarated movement',
'',
'      // Transform the image to make it grow and move with fingers',
'      const transform = `translate3d(${deltaX}px, ${deltaY}px, 0) scale(${imageElementScale})`;',
'      imageElement.style.transform = transform;',
'      imageElement.style.WebkitTransform = transform;',
'      imageElement.style.zIndex = "9999";',
'    }',
'  });',
'',
'  imageElement.addEventListener(''touchend'', (event) => {',
'    // console.log(''touchend'', event);',
'    // Reset image to it''s original format',
'    imageElement.style.transform = "";',
'    imageElement.style.WebkitTransform = "";',
'    imageElement.style.zIndex = "";',
'  });',
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'document.querySelectorAll(".pz-Media img:not(.pz-Image)").forEach(element => {',
'    pinchZoom(element);',
'});'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.t-Region--showCarouselControls .a-Region-carouselControl .a-Tabs-button {',
'    outline: 2px solid orange;',
'    --ut-carousel-button-background-color: blue;',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'11'
);
