wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(62017086996582833)
,p_name=>'Scorecards'
,p_parent_plug_id=>wwv_flow_imp.id(56200611705267025211)
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody:margin-top-md'
,p_component_template_options=>'#DEFAULT#:t-ContextualInfo-label--stacked'
,p_new_grid_row=>false
,p_grid_column_span=>3
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with curr_session as (',
'    select id tournament_session_id, week',
'     from wmg_tournament_sessions',
'     where TOURNAMENT_ID in (',
'         select ID',
'           from WMG_TOURNAMENTS',
'          where CURRENT_FLAG = ''Y''',
'     )',
'      and (',
'          completed_ind = ''N''',
'        or (completed_ind = ''Y'' and completed_on > current_timestamp - 1)',
'      )',
'    order by decode(completed_ind, ''N'', 1, 2)',
'    fetch first 1 rows only',
')',
', tp as (',
'  select 1',
'   from wmg_tournament_players tp',
'     , curr_session s',
'  where tp.tournament_session_id = s.tournament_session_id',
'    and tp.active_ind = ''Y''',
')',
'select scorecards, (select count(*) total_players from tp) total_players',
'from (',
'select count(*) scorecards',
'from wmg_tournament_results_v r',
'   , curr_session s',
'  where r.week = s.week',
')',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>true
,p_query_row_template=>wwv_flow_imp.id(47017591025581127384)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
