wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(44867808452441435)
,p_name=>'{Issues Report}'
,p_parent_plug_id=>wwv_flow_imp.id(72915101548951246)
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noBorder:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select p.player_name, p.verified_note',
', i.icon',
', i.name',
', i.description',
'from wmg_tournament_player_v p',
'   , wmg_issues i',
'where p.issue_code = i.code',
'  and p.issue_code = nvl(:P500_ISSUE_CODE, p.issue_code)',
'  and p.tournament_session_id in (',
'   select id ',
'     from wmg_tournament_sessions',
'     where TOURNAMENT_ID in (',
'         select ID',
'           from WMG_TOURNAMENTS',
'          where CURRENT_FLAG = ''Y''',
'     )',
'      and (',
'          completed_ind = ''N''',
'        or (completed_ind = ''Y'' and completed_on > current_timestamp - 1)',
'      )',
'    order by decode(completed_ind, ''N'', 1, 2)',
'    fetch first 1 rows only',
')',
'order by i.display_seq, p.player_name'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P500_ISSUE_CODE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(47017595232567127385)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'Y'
,p_csv_output_link_text=>'Download'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
