wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(136994834901323418)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Toggle Voting'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (',
'    select application_id, build_option_id, build_option_name, build_option_status',
'      from apex_application_build_options',
'     where build_option_name = ''Feature: Course Voting''',
'       and application_Id = :APP_ID',
'    )',
'loop',
'    if upper(c1.build_option_status) in (apex_application_admin.c_build_option_status_include, apex_application_admin.c_build_option_status_exclude) then',
'        apex_application_admin.set_build_option_status(  p_application_id => :APP_ID',
'                                         ,  p_id => c1.build_option_id',
'                                         ,  p_build_status => ',
'                                              case upper(c1.build_option_status)',
'                                                when apex_application_admin.c_build_option_status_include then apex_application_admin.c_build_option_status_exclude',
'                                                when apex_application_admin.c_build_option_status_exclude then apex_application_admin.c_build_option_status_include',
'                                              end );',
'    end if;',
'end loop;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'ENABLE_VOTING,DISABLE_VOTING'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_process_success_message=>'Voting status toggled'
,p_internal_uid=>136994834901323418
);
end;
