,p_plug_name=>'Registrations'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(47017557400631127370)
,p_plug_display_sequence=>40
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select registration_day, players, to_char(players) tooltip',
'from (',
'    select trunc(created_on) registration_day, count(*) players',
'    from wmg_tournament_players p',
'    where tournament_session_id in (',
'        select id',
'        from  wmg_tournament_sessions',
'       where tournament_id = :P530_ID',
'    )',
'    group by trunc(created_on) ',
')'))
,p_plug_source_type=>'PLUGIN_MULEDEV.CALENDAR_HEATMAP_REGION'
,p_plug_display_condition_type=>'EXISTS'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'        select 1',
'        from  wmg_tournament_sessions',
'       where tournament_id = :P530_ID',
'        and session_date >= to_date(''20230121'', ''YYYYMMDD'')'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'Y',
  'attribute_02', wwv_flow_string.join(wwv_flow_t_varchar2(
    'declare',
    'l_end_date date;',
    'begin',
    'select max(session_date)',
    'into l_end_date',
    '        from  wmg_tournament_sessions',
    '       where tournament_id = :P530_ID;',
    '  return to_char(l_end_date + 7, ''YYYYMMDD'');',
    ' exception ',
    ' when NO_DATA_FOUND then',
    '   return to_char(sysdate, ''YYYYMMDD'');',
    ' end;')))).to_clob
);
