,p_process_name=>'Handle Votes'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'',
'if :P532_CLEAR_VOTES_FLAG = ''Y'' then',
'  logger.log(''.. clear previous vote backup'');',
'  delete from wmg_course_vote_back;',
'  logger.log(''.. save vote backup'');',
'  insert into wmg_course_vote_back (',
'      id',
'    , course_id',
'    , player_id',
'    , vote',
'    , created_on',
'    , created_by',
'    , updated_on',
'    , updated_by',
'    )',
'    select   id',
'    , course_id',
'    , player_id',
'    , vote',
'    , created_on',
'    , created_by',
'    , updated_on',
'    , updated_by',
'    from wmg_course_vote;',
'',
'  logger.log(''..reset votes table'');',
'',
'  delete from wmg_course_vote;',
'end if;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P532_CLEAR_VOTES_FLAG = ''Y'''
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
