,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save Courses & Push Notifications'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'merge into wmg_tournament_courses c using ',
'  (select :P532_ID tournament_session_id',
'        , 1 course_no',
'        , :P532_EASY_COURSE_ID course_id',
'     from dual',
'  ) c2',
'  on (',
'      c.tournament_session_id = c2.tournament_session_id',
'  and c.course_no = c2.course_no',
'  )',
'when matched then',
'  update set c.course_id = c2.course_id',
'when not matched then',
'  insert (tournament_session_id, course_no, course_id)',
'  values (c2.tournament_session_id, c2.course_no, c2.course_id);',
'',
'merge into wmg_tournament_courses c using ',
'  (select :P532_ID tournament_session_id',
'        , 2 course_no',
'        , :P532_HARD_COURSE_ID course_id',
'     from dual',
'  ) c2',
'  on (',
'      c.tournament_session_id = c2.tournament_session_id',
'  and c.course_no = c2.course_no',
'  )',
'when matched then',
'  update set c.course_id = c2.course_id',
'when not matched then',
'  insert (tournament_session_id, course_no, course_id)',
'  values (c2.tournament_session_id, c2.course_no, c2.course_id);',
'',
'-- make the changes visible right away',
'apex_region.purge_cache (',
'    p_page_id    => 1',
');',
'',
'commit; -- Make sure everything up to now is saved.',
'',
'if (:REQUEST = ''CREATE'' and :P532_OPEN_REGISTRATION_ON is null) or (:REQUEST = ''SAVE'' and :P532_OPEN_NOTIFY_FLAG = ''Y'') then',
'-- apex_debug.message(''[%s] %s'', ''Save Courses & Push Notifications'', ''P532_ID='' || :P532_ID);',
'wmg_notification.notify_new_courses(p_tournament_session_id => :P532_ID);',
'end if;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':REQUEST != ''CLOSE_WEEKEND'' and :REQUEST != ''DELETE'''
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>56024166207057751661
);
