 p_id=>wwv_flow_imp.id(56180517293464849804)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_region_id=>wwv_flow_imp.id(56180502082020849795)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize form Wmg Tournament Sessions'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>56158061000602236801
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(30510208070551706)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Init'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'with w_ts as (',
'    select max(id) tournament_session_id',
'      from wmg_tournament_sessions',
'     where session_date = (',
'        select max(session_date)',
'          from wmg_tournament_sessions',
'         where tournament_id = :P532_TOURNAMENT_ID',
'        )',
'      and tournament_id = :P532_TOURNAMENT_ID',
')',
'select case when ts.round_num = 12 then 1 else ts.round_num + 1 end new_round_num',
'     , ts.session_date + 7',
'     , t.prefix_tournament || t.prefix_session || lpad(ts.round_num + 1, 2, ''0'')',
' into :P532_ROUND_NUM',
'    , :P532_SESSION_DATE',
'    , :P532_WEEK',
'from wmg_tournament_sessions ts',
'   , wmg_tournaments t',
'   , w_ts',
'where ts.tournament_id = t.id',
'  and ts.id = w_ts.tournament_session_id;',
'',
'exception',
'when NO_DATA_FOUND then',
'   if  :P532_TOURNAMENT_ID is not null then',
'   select prefix_tournament || prefix_session || ''01''',
'        , start_date',
'        , 1',
'     into :P532_WEEK',
'        , :P532_SESSION_DATE',
'        , :P532_ROUND_NUM',
'     from wmg_tournaments',
'     where id = :P532_TOURNAMENT_ID;',
'    else',
'       :P532_ROUND_NUM := 1;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P532_ID'
,p_process_when_type=>'ITEM_IS_NULL'
,p_internal_uid=>8053915207938703
);
end;
/
