prompt --application/pages/page_00580
begin
wwv_flow_imp_page.create_page(
 p_id=>580
,p_name=>'Player Moderation'
,p_alias=>'PLAYER-MODERATION'
,p_step_title=>'Player Moderation'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'03'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(128882796206773636)
,p_name=>'Player Moderation'
,p_template=>wwv_flow_imp.id(47017557400631127370)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select m.id',
'     , m.player_id',
'     , nvl(p.player_name, m.player_id) player_name',
'     , m.banned_flag',
'     , case ',
'         when m.banned_flag = ''Y'' then',
'           ''Banned''',
'         when m.timeout_flag = ''Y'' then',
'           case ',
'           when m.timeout_tournament_id is not null then',
'             ''Timed out for Season '' || t.code',
'           else',
'             ''Timed out until '' || to_char(m.timeout_end_date, ''DD-Mon-YYYY HH24:MI'')',
'           end',
'       else ''''',
'       end as moderation_status',
'     , m.timeout_flag',
'     , decode(m.notes, null, '''', ''Y'') as notes_flag',
'     , m.notes',
'     , decode(m.player_message, null, '''', ''Y'') as player_message_flag',
'     , m.player_message',
'     , m.active_ind',
'     , m.created_by',
'     , m.created_on',
'     , m.updated_by',
'     , m.updated_on',
'  from wmg_player_moderation m',
'  left join wmg_players_v p on m.player_id = p.id',
'  left join wmg_tournaments t on m.timeout_tournament_id = t.id'))
